struct T_EDU_BASE_D
{
	/// 저장시마다 데이터가 무작위로 바뀌도록 하기 위한 더미 데이터
	int nDummyA;
	int nDummyB;
	CString strID;
	int nDummyC;
	int nDummyD;
};

struct T_EDU_BASE_D_CH
{
	int nDummyA;
	int nDummyB;
	char strID[20];
	int nDummyC;
	int nDummyD;

	void ConvertToString(T_EDU_BASE_D& rData)
	{
		ConvertCharStr(strID, rData.strID, sizeof(strID));
	}	
	void ConvertToChar(T_EDU_BASE_D& rData)
	{
		ConvertStrChar(rData.strID, strID, sizeof(strID));
	}
};

struct T_EDUD_D
{
	CArray<T_EDU_BASE_D,T_EDU_BASE_D> aUser;
	void Initialize()
	{
		aUser.RemoveAll();
	}
	T_EDUD_D()
	{
		Initialize();
	}
	T_EDUD_D& operator=(T_EDUD_D& src)
	{
		aUser.Copy(src.aUser);
		return *this;
	}
};

