#define T_DCTL_K unsigned int
struct T_DCTL_BASE
{
	T_STOR_K KeyStory;
	double dRmax, dRmin;
	double dMinX, dMaxX, dMinY, dMaxY;
	void Initialize()
	{
		KeyStory=0;
		dRmax=1.0;
		dRmin=0.5;
		dMinX=dMaxX=dMinY=dMaxY=0.;
	}
};
#define T_DCTL_DT CArray<T_DCTL_BASE, T_DCTL_BASE&>
struct T_DCTL_D
{
	T_SPLC_K KeySpecX;
	T_SPLC_K KeySpecY;
	double F_EX;
	double F_EY;
	BOOL bBraceFrame_X;
	BOOL bBraceFrame_Y;
	BOOL bAutoKFactor;
	T_STLD_K KeyStld[5];
	T_DCTL_DT arReduction;
	int nReductType;  // 0:general, 1:china
	int nDesignType;  // 0:3-D  1:X-Z Plane  2: Y-Z Plane  3: X-Y Plane
	BOOL   bReduAxl;  // 580에서 추가 
	BOOL   bReduMom;  // 580에서 추가 
	BOOL   bReduShr;  // 580에서 추가 
	int nStructMatlType; // Add by GAY. PMS:4267. ('12.01.16). 구조재료형식 (0:철근콘크리트조, 1:철골철근콘크리트조, 2:비내력벽이 있는 강구조, 3:비내력벽이 없는 강구조)
	int nStructType;     // Add by GAY. PMS:4267. ('12.01.16). 구조형식 <- 구조재료형식에 따라 다음과 같이 구성.
											 // 철근콘크리트조 (0:프레임구조, 1:프레임+전단벽구조, 2:전단벽구조)
											 // 철골철근콘크리트조 (0:형강광가+RC튜브구조, 1:강광가+RC튜브구조, 2:강외통+RC튜브구조, 3:형강외통+RC튜브구조)
											 // 비내력벽이 있는/없는 강구조 (0:프레임구조, 1:프레임+중심브레이싱구조, 2:프레임+편심브레이싱구조)
	BOOL b02Q0UpLimit;   //add by maxiao 2012-5-24
	double d02Q0UpLimit; //add by maxiao 2012-5-24
	void Initialize()
	{
		KeySpecX=0;
		KeySpecY=0;
		F_EX=1.;
		F_EY=1.;
#if defined(_MGEN)
		bBraceFrame_X=TRUE;
		bBraceFrame_Y=TRUE;
#else
		bBraceFrame_X=FALSE;
		bBraceFrame_Y=FALSE;
#endif
		bAutoKFactor=FALSE;
		for(int i=0; i<5; i++)KeyStld[i]=0;
		arReduction.RemoveAll();
#if defined(_CH)
		nReductType = 1;
#else
		nReductType = 0;
#endif
		nDesignType = 0;
		bReduAxl = TRUE;
		bReduMom = FALSE;
		bReduShr = FALSE;
		nStructMatlType = 0;
		nStructType = 1;
		b02Q0UpLimit = FALSE;
		d02Q0UpLimit = 2.0;
	}
	T_DCTL_D()
	{
	}
	T_DCTL_D(T_DCTL_D& src)
	{
		*this = src;
	}
	T_DCTL_D& operator=(T_DCTL_D& src)
	{
		KeySpecX=src.KeySpecX;
		KeySpecY=src.KeySpecY;
		F_EX=src.F_EX;
		F_EY=src.F_EY;
		bBraceFrame_X=src.bBraceFrame_X;
		bBraceFrame_Y=src.bBraceFrame_Y;
		bAutoKFactor=src.bAutoKFactor;
		for(int i=0; i<5; i++)KeyStld[i]=src.KeyStld[i];
		arReduction.Copy(src.arReduction);
		nReductType = src.nReductType;
		nDesignType = src.nDesignType;
		bReduAxl = src.bReduAxl;
		bReduMom = src.bReduMom;
		bReduShr = src.bReduShr;
		nStructMatlType = src.nStructMatlType;
		nStructType     = src.nStructType;
		b02Q0UpLimit    = src.b02Q0UpLimit;
		d02Q0UpLimit    = src.d02Q0UpLimit;
		return *this;
	}
};
