struct T_PSCN_D // PSC Composite Shear Connector
{
	BOOL bBothIJ;        // I,J 같게 입력할 경우 TRUE, default=TRUE

	// 0=I,1=J.
	int nFaceState[2];   // 표면상태 0: 매우 매끄러움, 1: 매끄러움, 2:거침, 3:요철 표면
	double dAngle[2];    // [Degree] 전단연결재 기울기
	double dAw[2];       // [Area]   전단연결재 면적
	double dfy[2];       // [STRESS] 전단연결재 항복강도
	T_PSCN_IRS_D IRS_SConn;
	double dLs[2];
	double dAe[2];

	void Initialize()
	{
		bBothIJ = TRUE;
		nFaceState[0] = 0;
		nFaceState[1] = 0;
		dAngle[0] = 0.0;
		dAngle[1] = 0.0;
		dAw[0] = 0.0;
		dAw[1] = 0.0;
		dfy[0] = 0.0; 
		dfy[1] = 0.0;
		IRS_SConn.Initialize();
		dLs[0] = 0.0;
		dLs[1] = 0.0;
		dAe[0] = 0.0;
		dAe[1] = 0.0;
	}
	void Convert883(T_PSCN_D_883 &rData)
	{
		bBothIJ = rData.bBothIJ;
		nFaceState[0] = rData.nFaceState[0];
		nFaceState[1] = rData.nFaceState[1];
		dAngle[0] = rData.dAngle[0];
		dAngle[1] = rData.dAngle[1];
		dAw[0] = rData.dAw[0];
		dAw[1] = rData.dAw[1];
		dfy[0] = rData.dfy[0]; 
		dfy[1] = rData.dfy[1];
		IRS_SConn.Initialize();
		dLs[0] = 0.0;
		dLs[1] = 0.0;
		dAe[0] = 0.0;
		dAe[1] = 0.0;
	}
	void Convert891(T_PSCN_D_891 &rData)
	{
		bBothIJ = rData.bBothIJ;
		nFaceState[0] = rData.nFaceState[0];
		nFaceState[1] = rData.nFaceState[1];
		dAngle[0] = rData.dAngle[0];
		dAngle[1] = rData.dAngle[1];
		dAw[0] = rData.dAw[0];
		dAw[1] = rData.dAw[1];
		dfy[0] = rData.dfy[0];
		dfy[1] = rData.dfy[1];
		IRS_SConn = rData.IRS_SConn;
		dLs[0] = 0.0;
		dLs[1] = 0.0;
		dAe[0] = 0.0;
		dAe[1] = 0.0;
	}
};

