#define T_PSCS_K T_ELEM_K
struct T_PSCS_D_940 // PSC Composite Interface shear
{
	BOOL bBothIJ;           // I,J 같게 입력할 경우 TRUE, default=TRUE

	// 0=I,1=J.
	int nFaceState[2];   // 0: Roughened(CIP slab) 1:Monolithically  
	// 2:Intentionally roughened(LWC) 3:Intentionally roughened(NWC) 
	// 4:Not intentionally roughened 5: Anchored 
	double dBvi[2];      // [Length] Interface width
	double dAvf[2];      // [Area]   Area of Interface Shear Reinforcement Connector mm2/mm 이렇게 입력되고 있음.
	double dfy[2];       // [STRESS] 전단연결재 항복강도

	void Initialize()
	{
		bBothIJ = TRUE;
		memset(nFaceState, 0, sizeof(nFaceState));
		memset(dBvi, 0, sizeof(dBvi));
		memset(dAvf, 0, sizeof(dAvf));
		memset(dfy, 0, sizeof(dfy));
	}
};

struct T_PSCS_D // PSC Composite Interface shear
{
	BOOL bBothIJ;           // I,J 같게 입력할 경우 TRUE, default=TRUE

	// 0=I,1=J.
	int nFaceState[2];   // 0: Roughened(CIP slab) 1:Monolithically  
											 // 2:Intentionally roughened(LWC) 3:Intentionally roughened(NWC) 
											 // 4:Not intentionally roughened 5: Anchored 
	double dBvi[2];      // [Length] Interface width
	double dAvf[2];      // [Area]   Area of Interface Shear Reinforcement Connector mm2/mm 이렇게 입력되고 있음.
	double dfy[2];       // [STRESS] 전단연결재 항복강도
	double dAf[2];		 // [Degree] 전단연결재 각도, alpha_f

	void Initialize()
	{
		bBothIJ = TRUE;
		memset(nFaceState, 0, sizeof(nFaceState));
		memset(dBvi, 0, sizeof(dBvi));
		memset(dAvf, 0, sizeof(dAvf));
		memset(dfy, 0, sizeof(dfy));
		dAf[0] = 90.0;
		dAf[1] = 90.0;
	}
	void Convert940(T_PSCS_D_940& rData)
	{
		bBothIJ = rData.bBothIJ;
		memcpy(nFaceState, rData.nFaceState, sizeof(nFaceState));
		memcpy(dBvi, rData.dBvi, sizeof(dBvi));
		memcpy(dAvf, rData.dAvf, sizeof(dAvf));
		memcpy(dfy, rData.dfy, sizeof(dfy));
		dAf[0] = 90.0;
		dAf[1] = 90.0;
	}
};
