struct T_LCTP_D       // 620에서 처음 생성
{
	CArray<int, int> arLongType;
	CArray<int, int> arLongKey;
	CArray<int, int> arShtXType;
	CArray<int, int> arShtXKey;
	CArray<int, int> arShtYType;
	CArray<int, int> arShtYKey;
	void Initialize()
	{
		arLongType.RemoveAll();
		arLongKey.RemoveAll();
		arShtXType.RemoveAll();
		arShtXKey.RemoveAll();
		arShtYType.RemoveAll();
		arShtYKey.RemoveAll();    
	}
	T_LCTP_D()
	{
	}
	T_LCTP_D(T_LCTP_D& src)
	{
		*this = src;
	}
	T_LCTP_D& operator=(T_LCTP_D& src)
	{
		arLongType.Copy(src.arLongType);
		arLongKey.Copy(src.arLongKey);
		arShtXType.Copy(src.arShtXType);
		arShtXKey.Copy(src.arShtXKey);
		arShtYType.Copy(src.arShtYType);
		arShtYKey.Copy(src.arShtYKey);
		return *this;
	}
};
