		ConvertCharStr(strVerEndBarFy_Wall, rData.strVerEndBarFy_Wall, sizeof(strVerEndBarFy_Wall));
		ConvertCharStr(BEHorizontalRebarWall, rData.BEHorizontalRebarWall, sizeof(BEHorizontalRebarWall));
