#define T_DCBB_K unsigned int
struct T_DCBB_D
{
	CString MainRebarBeam;      // unit=NONE, default="".
	CString StirrupBarBeam;     // unit=NONE, default="".
	CString SideBarBeam;        // unit=NONE, default="".
	double  dT_Beam;            // unit=LENGTH, default=0.
	double  dB_Beam;            // unit=LENGTH, default=0.
	int     iSubRebarNum_Beam;  // unit=NONE, default=2.
	BOOL    bSpliceBeamJP;      // 철근배근지침(일본)적용옵션... unit=NONE, default=_JP(TRUE), 나머지(FALSE)
	int     iSpliceBeam;        // 0=0%, 1=50%, 2=100%      unit=NONE, default=1.
	int     iSpliceBeamSubType; // 0=폐쇄형, 1=U자형       unit=NONE, default=0.
	BOOL   bDoublyBeam;       // 7.2.0에서 추가 : Doubly Reinforced Beam Design     unit=NONE, default=TRUE
	double dDoublyBeam;       // 7.2.0에서 추가 : Doubly Reinforced Beam Design     unit=NONE, default=0.
	BOOL    bCheckRebarSpacing_Beam; // 7.4.1

	int iDgnClass; //7.6.1에서 추가 , 0:DCH 1:DCM

	void Initialize()
	{
		MainRebarBeam.Empty();
		StirrupBarBeam.Empty();
		SideBarBeam.Empty();
		dT_Beam = 0.0;
		dB_Beam = 0.0;
		iSubRebarNum_Beam = 2;
#ifdef _JP
		bSpliceBeamJP = TRUE;
#else
		bSpliceBeamJP = FALSE;
#endif
#if defined(_US) || defined(_RUS)
		iSpliceBeam = 0;
#else
		iSpliceBeam = 1;
#endif
		iSpliceBeamSubType = 0;
		bDoublyBeam = TRUE;
		dDoublyBeam = 1.0;
		bCheckRebarSpacing_Beam = TRUE;
		iDgnClass = 0;
	}
};
struct T_DCBB_UDRD_D
{
	T_DCBB_K key;
	T_DCBB_D data;
};
