#define T_REBB_KEY unsigned int
union T_REBB_K
{
	T_REBB_KEY keymap;
	struct
	{
		unsigned int sectK : 20;
		unsigned int subSectK : 12;  
	}key;

    bool operator < (const T_REBB_K& src) const
    {
        if ( key.sectK < src.key.sectK )
            return true;
        else if ( key.sectK == src.key.sectK && key.subSectK < src.key.subSectK )
            return true;

        return false;
    }
};

