struct T_REBC_D
{
	int nHoopType;       // 1=Tied  2=Spiral
	CString MainRebarName;
	int nQrb;
	int nRow;
	double dConcCenter;
	CString SubRebarName;
	double dSubRebarSpace;
	int iSubRebarNum[2];     // 6.6.0에서 배열로 변환 : 그 전에는 하나만 사용
	int iBCJointRebarNum; // 7.7.0에서 추가
	CString SubRebarName2;      // Center   7.7.0
	double dSubRebarSpace2;     // Center
	int iSubRebarNum2[2];       // Center
	BOOL bUseCornerRebar;  // 805에서 추가. // Add/Modify by Seungjun PMS:4496  '20120619 RC 보/기둥 철근종류 여러 개 지정 (코너철근 등, 설계없이 검토만)
	CString CornerRebarName;  // 805에서 추가. // Add/Modify by Seungjun PMS:4496  '20120619 RC 보/기둥 철근종류 여러 개 지정 (코너철근 등, 설계없이 검토만)
	BOOL bSameRebarEndNCenter;  // 850에서 추가 전단보강근을 Center와 End를 같게 하는 옵션
	void Initialize()
	{
		nHoopType=0;
		MainRebarName.Empty();
		nQrb=0;
		nRow=0;
		dConcCenter=0.;
		SubRebarName.Empty();
		dSubRebarSpace=0.;
		iSubRebarNum[0] = iSubRebarNum[1] =2;
		iBCJointRebarNum = 0;
		SubRebarName2.Empty();
		dSubRebarSpace2=0.;
		iSubRebarNum2[0] = iSubRebarNum2[1] =2;
		bUseCornerRebar = FALSE;
		CornerRebarName.Empty();
		bSameRebarEndNCenter = TRUE;
	}

	BOOL operator==(const T_REBC_D& src) const
	{
		return (nHoopType == src.nHoopType && MainRebarName == src.MainRebarName && nQrb == src.nQrb &&
						nRow == src.nRow && fabs(dConcCenter - src.dConcCenter) < 1.e-10 && SubRebarName == src.SubRebarName &&
						fabs(dSubRebarSpace - src.dSubRebarSpace) < 1.e-10 && iSubRebarNum[0] == src.iSubRebarNum[0] &&
						iSubRebarNum[1] == src.iSubRebarNum[1] && iBCJointRebarNum == src.iBCJointRebarNum &&
						SubRebarName2 == src.SubRebarName2 && fabs(dSubRebarSpace2 - src.dSubRebarSpace2) < 1.e-10 &&
						iSubRebarNum2[0] == src.iSubRebarNum2[0] && iSubRebarNum2[1] == src.iSubRebarNum2[1] &&
						bUseCornerRebar == src.bUseCornerRebar && CornerRebarName == src.CornerRebarName && bSameRebarEndNCenter == src.bSameRebarEndNCenter);
	}
};
