struct T_REBW_D
{
	BOOL bUseModelThik;
	double dThickness;
	CString VerticalRebarName;
	double dVerticalRebarSpace;
	CString EndRebarName;
	int nNumEndRebar;
	double dEndRebarSpace;
	CString HorizonRebarName;
	double dHorizonRebarSpace;
	double dDw;
	double dDe;

	CString BEHorizonRebarName;  // 7.8.5
	double  dBEHorizonRebarSpace;   // 7.8.5

	double  dBELength;   // 8.7.0

	CArray<UINT,UINT> aStorK;
	void Initialize()
	{
		bUseModelThik=TRUE;
		dThickness=0.;
		VerticalRebarName.Empty();
		dVerticalRebarSpace=0.;
		EndRebarName.Empty();
		nNumEndRebar=0;
		dEndRebarSpace=0.;
		HorizonRebarName.Empty();
		dHorizonRebarSpace=0.;
		dDw=0.;
		dDe=0.;
		aStorK.RemoveAll();
		BEHorizonRebarName.Empty();
		dBEHorizonRebarSpace = 0.2;
		dBELength = 0.;
	}
	T_REBW_D() {Initialize();}
	T_REBW_D& operator=(T_REBW_D& src)
	{
		bUseModelThik=src.bUseModelThik;
		dThickness=src.dThickness;
		VerticalRebarName = src.VerticalRebarName;
		dVerticalRebarSpace=src.dVerticalRebarSpace;
		EndRebarName = src.EndRebarName;
		nNumEndRebar=src.nNumEndRebar;
		dEndRebarSpace=src.dEndRebarSpace;
		HorizonRebarName = src.HorizonRebarName;
		dHorizonRebarSpace=src.dHorizonRebarSpace;
		dDw=src.dDw;
		dDe=src.dDe;
		aStorK.Copy(src.aStorK);
		BEHorizonRebarName = src.BEHorizonRebarName;
		dBEHorizonRebarSpace = src.dBEHorizonRebarSpace;
		dBELength = src.dBELength;
		return *this;
	}
	T_REBW_D(T_REBW_D& src)
	{
		*this = src;
	}
	BOOL operator==(const T_REBW_D& src) const
	{
		if(bUseModelThik       != src.bUseModelThik      ) return FALSE;
		if(fabs(dThickness - src.dThickness) > 1.e-10    ) return FALSE;
		if(VerticalRebarName   != src.VerticalRebarName  ) return FALSE;
		if(fabs(dVerticalRebarSpace - src.dVerticalRebarSpace) > 1.e-10 ) return FALSE;
		if(EndRebarName        != src.EndRebarName       ) return FALSE;
		if(nNumEndRebar        != src.nNumEndRebar       ) return FALSE;
		if(fabs(dEndRebarSpace - src.dEndRebarSpace) > 1.e-10 ) return FALSE;
		if(HorizonRebarName    != src.HorizonRebarName   ) return FALSE;
		if(dHorizonRebarSpace  != src.dHorizonRebarSpace ) return FALSE;
		if(fabs(dDw - src.dDw) > 1.e-10                  ) return FALSE;
		if(fabs(dDe - src.dDe) > 1.e-10                  ) return FALSE;
		if(BEHorizonRebarName  != src.BEHorizonRebarName ) return FALSE;
		if(fabs(dBEHorizonRebarSpace - src.dBEHorizonRebarSpace) > 1.e-10) return FALSE;
		if(fabs(dBELength - src.dBELength) > 1.e-10      ) return FALSE;

		// aStorK 는 비교 제외
		return TRUE;
	}
	BOOL operator!=(const T_REBW_D& src) const
	{
		return !( *this == src );
	}
};
