struct T_RBMS_D_835
{
	CString strName          ;
	CString strBasicRebarName;
	double  dBasicRebarSpace ;    
	CString strAdd1RebarName ;
	double  dAdd1RebarSpace  ;  
	CString strAdd2RebarName ;  
	double  dAdd2RebarSpace  ; // Add1과 동일한 값으로 사용된다.
	double  dCover           ;
	int     nLayerType       ; // 0=Top-Dir1, 1=Bot-Dir1, 2=Top-Dir2, 3=Bot-Dir2  

	void Initialize()
	{
		nLayerType = 0;
		strName.Empty();
		strBasicRebarName.Empty();
		strAdd1RebarName .Empty();
		strAdd2RebarName .Empty();    
		dBasicRebarSpace = 0.0;
		dAdd1RebarSpace  = 0.0;
		dAdd2RebarSpace  = 0.0;
		dCover           = 0.0;  
	}
	T_RBMS_D_835()    {     Initialize();      }
	BOOL operator==(const T_RBMS_D_835& src) const
	{
		if(nLayerType        != src.nLayerType       ) return FALSE; 
		if(strName           != src.strName          ) return FALSE;
		if(strBasicRebarName != src.strBasicRebarName) return FALSE;
		if(strAdd1RebarName  != src.strAdd1RebarName ) return FALSE;
		if(strAdd2RebarName  != src.strAdd2RebarName ) return FALSE;
		if(!strBasicRebarName.IsEmpty())
		{
			if(fabs(dBasicRebarSpace - src.dBasicRebarSpace) > 1.e-10 ) return FALSE;    
		}
		if(!strAdd1RebarName.IsEmpty())
		{
			if(fabs(dAdd1RebarSpace - src.dAdd1RebarSpace) > 1.e-10 ) return FALSE;    
		}
		if(!strAdd2RebarName.IsEmpty())
		{
			if(fabs(dAdd2RebarSpace  - src.dAdd2RebarSpace) > 1.e-10 ) return FALSE;    
		}
		if(fabs(dCover - src.dCover) > 1.e-10 ) return FALSE;    

		return TRUE;
	}
	BOOL operator!=(const T_RBMS_D_835& src) const
	{
		return !( *this == src );
	}
	BOOL IsSameData(T_RBMS_D_835& src, BOOL bLayer=TRUE)
	{
		if(bLayer && (nLayerType != src.nLayerType)) return FALSE;
		if(strBasicRebarName != src.strBasicRebarName) return FALSE;
		if(strAdd1RebarName  != src.strAdd1RebarName ) return FALSE;
		if(strAdd2RebarName  != src.strAdd2RebarName ) return FALSE;    
		if(fabs(dBasicRebarSpace - src.dBasicRebarSpace) > 1.e-10 ) return FALSE;
		if(fabs(dAdd1RebarSpace  - src.dAdd1RebarSpace ) > 1.e-10 ) return FALSE;
		if(fabs(dAdd2RebarSpace  - src.dAdd2RebarSpace ) > 1.e-10 ) return FALSE;
		if(fabs(dCover           - src.dCover          ) > 1.e-10 ) return FALSE;

		return TRUE;
	}
};

