		{
			if(fabs(dPunchRebarSpace - src.dPunchRebarSpace) > 1.e-10 ) return FALSE;    
		}
		if(!strStudRebarName.IsEmpty())
		{
			if(fabs(dStudRebarSpace  - src.dStudRebarSpace) > 1.e-10 ) return FALSE;    
		}

