#define T_RBST_K unsigned int

struct T_RBST_D
{  
	int     nLayerType    ; // 0=Top-Main, 1=Bot.-Main
	CString strName       ;
	CString strRebarName_I;
	CString strRebarName_C;
	CString strRebarName_J;
	double  dRebarSpace_I ; 
	double  dRebarSpace_C ; 
	double  dRebarSpace_J ; 
	double  dCover        ;
	void Initialize()
	{
		nLayerType = 0;
		strName.Empty();
		strRebarName_I.Empty();
		strRebarName_C.Empty();
		strRebarName_J.Empty();
		dRebarSpace_I = 0.0; 
		dRebarSpace_C = 0.0; 
		dRebarSpace_J = 0.0; 
		dCover        = 0.0;    
	}
	T_RBST_D() { Initialize(); }
	BOOL operator==(const T_RBST_D& src) const
	{
		if(nLayerType     != src.nLayerType       ) return FALSE; 
		if(strName        != src.strName          ) return FALSE;
		if(strRebarName_I != src.strRebarName_I  ) return FALSE;
		if(strRebarName_C != src.strRebarName_C) return FALSE;
		if(strRebarName_J != src.strRebarName_J  ) return FALSE;
		if(!strRebarName_I.IsEmpty() && fabs(dRebarSpace_I - src.dRebarSpace_I) > 1.e-10 ) return FALSE;    
		if(!strRebarName_C.IsEmpty() && fabs(dRebarSpace_C - src.dRebarSpace_C) > 1.e-10 ) return FALSE;
		if(!strRebarName_J.IsEmpty() && fabs(dRebarSpace_J - src.dRebarSpace_J) > 1.e-10 ) return FALSE;
		if(fabs(dCover - src.dCover) > 1.e-10 ) return FALSE;

		return TRUE;
	}
	BOOL operator!=(const T_RBST_D& src) const
	{
		return !( *this == src );
	}
	BOOL IsSameData(T_RBST_D& src, BOOL bLayer=TRUE)
	{
		if(bLayer && (nLayerType != src.nLayerType)) return FALSE;
		if(strRebarName_I != src.strRebarName_I) return FALSE;
		if(strRebarName_C != src.strRebarName_C) return FALSE;
		if(strRebarName_J != src.strRebarName_J) return FALSE;
		if(fabs(dRebarSpace_I - src.dRebarSpace_I) > 1.e-10 ) return FALSE;    
		if(fabs(dRebarSpace_C - src.dRebarSpace_C) > 1.e-10 ) return FALSE;
		if(fabs(dRebarSpace_J - src.dRebarSpace_J) > 1.e-10 ) return FALSE;
		if(fabs(dCover        - src.dCover       ) > 1.e-10 ) return FALSE;
		return TRUE;
	}   
};

