struct T_FSTL_KEY
{
	UINT ElemK;
	UINT DgnLcomK;
	int  nPos;  // 0:I, 1:M, 2:J
	operator unsigned long() {return (DgnLcomK<<24) + (ElemK<<1) + nPos; }

	BOOL operator==(const T_FSTL_KEY& rKey) const
	{
		if(ElemK == rKey.ElemK && DgnLcomK == rKey.DgnLcomK && nPos == rKey.nPos) 
			return TRUE;
		else 
			return FALSE;
	}
};

struct T_FSTL_BASE
{
	BOOL bCheck;
	UINT LcomK;
	UINT DgnLcomK;
	int iMax; //MIN=0, MAX=1
	// Add by GAY. MNET:2683. ('07.05.12). Load Component Type (1~10:FX,FY,FZ,MX,MY,MZ,Bi-Moment,Twisting Moment,Warping Moment,Stress).
	UINT iCompType;
	double dFxx, dFyy, dFzz;
	double dMux, dMuy, dMuz;
	double dMbi, dTst, dTwp; // Bi-Moment,Twisting Moment,Warping Moment.
	void Initialize()
	{
		bCheck = FALSE;
		LcomK = 0;
		DgnLcomK = 0;
		iMax = 0;
		iCompType = 0;
		dFxx = dFyy = dFzz = 0.0;
		dMux = dMuy = dMuz = 0.0;
		dMbi = dTst = dTwp = 0.0;
	}
};

struct T_FSTL_D
{
	UINT ElemK;
	BOOL bCheck;
	CArray<T_FSTL_BASE,T_FSTL_BASE> FstlBase[5]; //I, 1/4 M, 3/4, J
	void Initialize()
	{
		ElemK = 0;
		bCheck = FALSE;
		for(int i = 0; i < 5; i++)
		{
			FstlBase[i].RemoveAll();
		}
	}

	T_FSTL_D()
	{
	}
	T_FSTL_D(T_FSTL_D& src)
	{
		*this = src;
	}
	T_FSTL_D& operator=(T_FSTL_D& src)
	{
		ElemK = src.ElemK;
		bCheck = src.bCheck;
		for(int i=0; i<5; i++) FstlBase[i].Copy(src.FstlBase[i]);
		return *this;
	}
};

struct T_FSTL_D_RW
{
	UINT ElemK;
	BOOL bCheck;
	int nNumFstlBase[5];
	void Initialize()
	{
		ElemK = 0;
		bCheck = FALSE;
		for(int i=0; i<5; i++) nNumFstlBase[i] = 0;
	}
	void GetFstl(T_FSTL_D& rData)
	{        
	}
	void SetFstl(const T_FSTL_D& rData)
	{
		ElemK = rData.ElemK;
		bCheck = rData.bCheck;
		for(int i=0; i<5; i++)  nNumFstlBase[i] = (int)rData.FstlBase[i].GetSize();
	}  
};

