struct T_PROP_EFF_BASE
{
	UINT OrgLcomK;
	UINT DgnLcomK;

	double dA_eff;
	double dIy_eff;
	double dIz_eff;
	double dWy_eff;
	double dWz_eff;
	double dIt_eff;
	double dIw_eff;
	double dCy_eff;
	double dCz_eff;

	void Initialize()
	{
		OrgLcomK=0;
		DgnLcomK=0;
		dA_eff   = 0.0;
		dIy_eff  = 0.0;
		dIz_eff  = 0.0;
		dWy_eff  = 0.0;
		dWz_eff  = 0.0;
		dIt_eff  = 0.0;
		dIw_eff  = 0.0;
		dCy_eff  = 0.0;
		dCz_eff  = 0.0;
	}

	T_PROP_EFF_BASE() {Initialize();}
	T_PROP_EFF_BASE(const T_PROP_EFF_BASE& src) { *this = src; }
	T_PROP_EFF_BASE& operator=(const T_PROP_EFF_BASE& src) 
	{
		OrgLcomK = src.OrgLcomK;
		DgnLcomK = src.DgnLcomK;
		dA_eff  = src.dA_eff;
		dIy_eff = src.dIy_eff;
		dIz_eff = src.dIz_eff;
		dWy_eff = src.dWy_eff;
		dWz_eff = src.dWz_eff;
		dIt_eff = src.dIt_eff;
		dIw_eff = src.dIw_eff;
		dCy_eff = src.dCy_eff;
		dCz_eff = src.dCz_eff;

		return (*this);
	}
	
};


struct T_SDEP_BASE
{
	BOOL bCheck;
	T_PROP_EFF_BASE PropUls;
	T_PROP_EFF_BASE PropSls;

	void Initialize()
	{
		bCheck = FALSE;
		PropUls.Initialize();
		PropSls.Initialize();
	}

	T_SDEP_BASE() {Initialize();}
	T_SDEP_BASE(const T_SDEP_BASE& src) { *this = src; }
	T_SDEP_BASE& operator=(const T_SDEP_BASE& src) 
	{
		bCheck = src.bCheck;
		PropUls = src.PropUls;
		PropSls  = src.PropSls;
		return (*this);
	}

};


struct T_SDEP_D  // Steel Design Effective Properties
{
	UINT ElemK;
	BOOL bCheck;
	T_SDEP_BASE SdepBase[5]; //I, 1/4, M, 3/4, J
	void Initialize()
	{
		ElemK = 0;
		bCheck = FALSE;
		for(int i = 0; i < 5; i++)
		{
			SdepBase[i].Initialize();
		}
	}

	T_SDEP_D() {Initialize();}
	T_SDEP_D(const T_SDEP_D& src) { *this = src; }
	T_SDEP_D& operator=(const T_SDEP_D& src) 
	{
		ElemK = src.ElemK;
		bCheck = src.bCheck;

		for(int i=0; i<5; i++) SdepBase[i] =src.SdepBase[i];
		return *this;

	}
};

