// Flange의 구성 Data
struct T_STED_LDATA
{
	// Pipe일 경우는 dBothFix_b에 반지름(R), dBothFix_t에 두께를 입력한다. 
	BOOL bPanel; // 패널 존재 유무, 양연지지에만 있는 것으로 한다. 
	int in; // 패널 수 
	double dCant1_b, dBothFix_b, dCant2_b; // 판의 고정연 사이의 거리 b
	double dCant1_t, dBothFix_t, dCant2_t; // 두께 
	BOOL bCant1, bBothFix, bCant2; // 존재 유무 
	double dfcal1, dfcal2; // 표 3.4.4 자유돌출판의 국부좌굴에 대한 허용응력 
	double dCant1_t_min, dCant2_t_min; // 자유돌출부 최소두께.(양연지지는 T_STDR_BF_DATA에)
	BOOL bChk_Cant1_t_min, bChk_Cant2_t_min; // 최소두께 검토(양연지지는 T_STDR_BF_DATA에)
	// General Section에만 사용. 
	double db_sum; // dCant1_b + dBothFix_b + dCant2_b
	double dt_max; // Line중 최대두께.
	
	void Initialize()
	{
		bPanel=FALSE; 
		in=0; // 패널 수 
		dCant1_b=dBothFix_b=dCant2_b=0.0; 
		dCant1_t=dBothFix_t=dCant2_t=0.0; 
		bCant1=bBothFix=bCant2=FALSE;
		dfcal1=dfcal2=0.0; 
		dCant1_t_min=dCant2_t_min=0.0;
		bChk_Cant1_t_min=bChk_Cant2_t_min=FALSE;
		db_sum=0.0;
		dt_max=0.0;
	}
};

