	double dAw_334_T, dAw_334_B, dAw_334_L, dAw_334_R; // Unit=Area
	double dAc_334_T, dAc_334_B, dAc_334_L, dAc_334_R; // Unit=Area
	double db_334_T,  db_334_B, db_334_L, db_334_R;    // Unit=Length
