	double dfbagzLW, dfbagzRW;  
	double dfbagyTL, dfbagyTR, dfbagyBR, dfbagyBL;
	double dfbagzTL, dfbagzTR, dfbagzBR, dfbagzBL;
	double dfbaoTF, dfbaoBF, dfbaoLW, dfbaoRW;  
