struct T_SDRT_BASE
{
	BOOL bCheck;
	BOOL bOK;
	double dStress[4];          // Stress Check 1,2,3,4  
	double dAlwStress[4];       // Allowable Stress 1,2,3,4
	double dShrStressY;         // Shear Stress Check Y축  
	double dShrStressZ;         // Shear Stress Check Z축  
	double dAlwShrStressY;      // Allowable Shear Stress Check Y축  
	double dAlwShrStressZ;      // Allowable Shear Stress Check Z축  
	double dCombStressRatio;    // Combination Stress Check
	double dAlwCombStressRatio; // Combination Stress Check
	double dBuckRatioY;         // Buckling Stability Check Y
	double dBuckRatioZ;         // Buckling Stability Check Z
	double dAlwBuckRatioY;      // Allowable Buckling Stability Check Y
	double dAlwBuckRatioZ;      // Allowable Buckling Stability Check Z

	void Initialize()
	{
		bCheck = FALSE;
		bOK = FALSE;
		for(int i=0; i<4; i++)
		{
			dStress[i] = 0.0;    
			dAlwStress[i] = 0.0; 
		}
		dShrStressY = 0.0;   
		dShrStressZ = 0.0;   
		dAlwShrStressY = 0.0;
		dAlwShrStressZ = 0.0;
		dCombStressRatio = 0.0;   
		dAlwCombStressRatio = 0.0;
		dBuckRatioY = 0.0;   
		dBuckRatioZ = 0.0;   
		dAlwBuckRatioY = 0.0;
		dAlwBuckRatioZ = 0.0;
	}
};

