struct T_SDRD_BASE
{
	BOOL bCheck;
	double dTensStress[5];      // 인장응력 0=Maximum,1,2,3,4  
	double dCompStress[5];      // 압축응력 0=Maximum,1,2,3,4  
	double dAlwTensStress[5];   // 허용인장응력 0=Maximum,1,2,3,4
	double dAlwCompStress[5];   // 허용압축응력 0=Maximum,1,2,3,4
	double dShrStressY;         // 전단응력 Y축  
	double dShrStressZ;         // 전단응력 Z축  
	double dAlwShrStressY;      // 허용전단응력 Y축  
	double dAlwShrStressZ;      // 허용전단응력 Z축  
	double dCompStressRatio;    // 합성응력검토 
	double dAlwCompStressRatio; // 합성응력검토 제한값.
	double dBuckRatioY[5];      // 좌굴안정검토 Y 0=Maximum,1,2,3,4
	double dBuckRatioZ[5];      // 좌굴안정검토 Z 0=Maximum,1,2,3,4
	double dAlwBuckRatio;       // 허용좌굴안정검토 제한값( Y,Z 같이 사용)  

	// For LSD Design
	double dPu;
	double dPn;
	double dMuy;
	double dMny;
	double dMuz;
	double dMnz;
	double dVuy;
	double dVny;
	double dVuz;
	double dVnz;
	double dCombinedRat;

	void Initialize()
	{
		bCheck = FALSE;
		for(int i=0; i<5; i++)
		{
			dTensStress[i] = 0.0;  
			dCompStress[i] = 0.0;
			dAlwTensStress[i] = 0.0;
			dAlwCompStress[i] = 0.0;
			dBuckRatioY[i] = 0.0; 
			dBuckRatioZ[i] = 0.0;
		}
		dShrStressY = 0.0;   
		dShrStressZ = 0.0;   
		dAlwShrStressY = 0.0;
		dAlwShrStressZ = 0.0;
		dCompStressRatio = 0.0;   
		dAlwCompStressRatio = 0.0;
		dAlwBuckRatio = 0.0;    

	dPu          = 0.0;
	dPn          = 0.0;
	dMuy         = 0.0;
	dMny         = 0.0;
	dMuz         = 0.0;
	dMnz         = 0.0;
	dVuy         = 0.0;
	dVny         = 0.0;
	dVuz         = 0.0;
	dVnz         = 0.0;
	dCombinedRat = 0.0;
	}
};

