	CString res_sCornerbarNa;  // 최대 8자
	// Only Checking Data.
	CString strChkStrn;
	double res_dpPnmax;
	double res_dMFy;  // Moment Magnification Factor.
	double res_dMFz;  // Moment Magnification Factor.
	double res_dPu;
	double res_dMcy; // Factored Moment.
	double res_dMcz; // Factored Moment.
	// Only Design Data.
	double res_dAsV;
	//double res_dAsH;
	int res_iMainbarNum; // 개수, 가로줄수
	int res_iMainbarArr; // 개수, 가로줄수
	//double res_dSubbarDist;
	double res_dRatM;     // 5.0.0에서 추가:일본 규준 때문
	double res_dRealRota; // 5.6.0에서 추가
	double res_dRatNc[4]; // 6.0.0에서 추가 // Modify by GAY. PMS:4267. ('12.01.11). Array Size : 3->4. (0=Non EQ,1=EQ,2=D+0.5L,3=EQ_lim)
	double res_dAdhtay;		// 6.6.0에서 추가
	double res_dAdhfay;		// 6.6.0에서 추가
	double res_dAdhtaz;		// 6.6.0에서 추가
	double res_dAdhfaz;		// 6.6.0에서 추가
	// Add by SeungJun (`06.05.04)
	// NO.1953 RC Beam-Column Flexural Capacity Ratio
	// For Strong Column Weak Beam Design
	double res_dPupMn[2];  // 7.1.0에서 추가, 0:I단, 1:J단
	double res_dPupMny[2]; // 7.1.0에서 추가
	double res_dPupMnz[2]; // 7.1.0에서 추가
	// Seungjun-20091119 EC2:04 Ductile design.
	double res_dk1y[2];
	double res_dk1z[2];  
	// Add by ZINU.('06.12.06). NO:2484.
	double res_ddT;	// 7.2.0
	// Coded by Seungjun ('20070308) MNet:No.2669.
	double res_dVey[2];
	double res_dVez[2];
	// Coded by SeungJun MNET:3433  '20080523
	BOOL   res_bShearEQ[2]; // 750 : Local-z, Local-y.
	int    res_iLcom;  // Add by GAY. MNET:XXXX. ('09.04.10)		
	// MQC:3351-Seungjun-20100503 기둥 최소철근비 체크.
	double res_dRhomin;
	double res_dRhomax;

