struct T_RDRB_BASE
{
	//Top 철근의 경우 좌우측 모서리의 배근된 철근은 언제나 TopCornerBar에 넣어야 하고,
	//나머지를 TopMiddleBar에 넣는다.
	//ex) Top 3-D22 ==> TopCorenBar 2-D22, TopMiddieBar 1-D22
	T_RNUM_BASE TopCornerBar[2];
	T_RNUM_BASE TopMiddleBar[2];
	T_RNUM_BASE BottomBar[2];	
	T_RSPC_BASE StirrupBar;
	T_RNUM_BASE SideBar;

	//필요철근량
	double ReqAsTopCorner;
	double ReqAsTopMiddle;
	double ReqAsBottom;
	double ReqAsTorsion;
	double ReqAsStirrup;

	double MaxRebarRatio;
	double MinRebarRatio;
		
	void Initialize()
	{
		for(int i=0 ; i<2 ; i++)
		{
			TopCornerBar[i].Initialize();
			TopMiddleBar[i].Initialize();
			BottomBar[i].Initialize();	
		}		
		StirrupBar.Initialize();
		SideBar.Initialize();

		ReqAsTopCorner	= 0.0;
		ReqAsTopMiddle	= 0.0;
		ReqAsBottom			= 0.0;
		ReqAsTorsion		= 0.0;
		ReqAsStirrup		= 0.0;
		
		MaxRebarRatio		= 0.0;
		MinRebarRatio		= 0.0;
	}
	T_RDRB_BASE() {}
	T_RDRB_BASE(const T_RDRB_BASE& src) { *this = src; }
	T_RDRB_BASE& operator=(const T_RDRB_BASE& src)
	{
		for(int i=0 ; i<2 ; i++)
		{
			TopCornerBar[i] = src.TopCornerBar[i];
			TopMiddleBar[i] = src.TopMiddleBar[i];
			BottomBar[i] = src.BottomBar[i];			
		}	
		
		StirrupBar = src.StirrupBar;
		SideBar = src.SideBar;

		ReqAsTopCorner = src.ReqAsTopCorner;
		ReqAsTopMiddle = src.ReqAsTopMiddle;		
		ReqAsBottom = src.ReqAsBottom;
		ReqAsTorsion = src.ReqAsTorsion;		
		ReqAsStirrup = src.ReqAsStirrup;

		MaxRebarRatio = src.MaxRebarRatio;		
		MinRebarRatio = src.MinRebarRatio;
		return *this;
	}
};
struct T_RDRB_BASE_CH
{
	T_RNUM_BASE_CH TopCornerBar[2];
	T_RNUM_BASE_CH TopMiddleBar[2];
	T_RNUM_BASE_CH BottomBar[2];	  
	T_RSPC_BASE_CH StirrupBar;
	T_RNUM_BASE_CH SideBar;

	//필요철근량
	double ReqAsTopCorner;
	double ReqAsTopMiddle;
	double ReqAsBottom;
	double ReqAsTorsion;
	double ReqAsStirrup;

	double MaxRebarRatio;
	double MinRebarRatio;

	void Initialize()
	{
		for(int i=0 ; i<2 ; i++)
		{
			TopCornerBar[i].Initialize();
			TopMiddleBar[i].Initialize();
			BottomBar[i].Initialize();	
		}
		StirrupBar.Initialize();
		SideBar.Initialize();
	
		ReqAsTopCorner	= 0.0;
		ReqAsTopMiddle	= 0.0;
		ReqAsBottom			= 0.0;
		ReqAsTorsion		= 0.0;
		ReqAsStirrup		= 0.0;
		
		MaxRebarRatio		= 0.0;
		MinRebarRatio		= 0.0;
	}

	void ConvertToString(T_RDRB_BASE& rData)
	{
		int i=0;
		for(i=0 ; i<2 ; i++)	TopCornerBar[i].ConvertToString(rData.TopCornerBar[i]);
		for(i=0 ; i<2 ; i++)	TopMiddleBar[i].ConvertToString(rData.TopMiddleBar[i]);
		for(i=0 ; i<2 ; i++)		 BottomBar[i].ConvertToString(rData.BottomBar[i]);
		StirrupBar.ConvertToString(rData.StirrupBar);
		SideBar.ConvertToString(rData.SideBar);
		
		rData.ReqAsTopCorner=ReqAsTopCorner;
		rData.ReqAsTopMiddle=ReqAsTopMiddle;
		rData.ReqAsBottom=ReqAsBottom;
		rData.ReqAsTorsion=ReqAsTorsion;
		rData.ReqAsStirrup=ReqAsStirrup;

		rData.MaxRebarRatio=MaxRebarRatio;
		rData.MinRebarRatio=MinRebarRatio;
	}
	void ConvertToChar(T_RDRB_BASE& rData)
	{
		int i=0;
		for(i=0 ; i<2 ; i++)	TopCornerBar[i].ConvertToChar(rData.TopCornerBar[i]);
		for(i=0 ; i<2 ; i++)	TopMiddleBar[i].ConvertToChar(rData.TopMiddleBar[i]);
		for(i=0 ; i<2 ; i++)	 	 BottomBar[i].ConvertToChar(rData.BottomBar[i]);
		StirrupBar.ConvertToChar(rData.StirrupBar);
		SideBar.ConvertToChar(rData.SideBar);
		
		ReqAsTopCorner=rData.ReqAsTopCorner;		
		ReqAsTopMiddle=rData.ReqAsTopMiddle;
		ReqAsBottom=rData.ReqAsBottom;
		ReqAsTorsion=rData.ReqAsTorsion;
		ReqAsStirrup=rData.ReqAsStirrup;

		MaxRebarRatio=rData.MaxRebarRatio;
		MinRebarRatio=rData.MinRebarRatio;
	}
};
