struct T_FBEM_KEY
{
	UINT ElemK;
	UINT DgnLcomK;
	int  nPos;  // 0:I, 1:1/4, 1:2/4, 3:3/4, 4:J
	operator unsigned long() {return (DgnLcomK<<24) + (ElemK<<1) + nPos; }

	BOOL operator==(const T_FBEM_KEY& rKey) const
	{
		if(ElemK == rKey.ElemK && DgnLcomK == rKey.DgnLcomK && nPos == rKey.nPos) 
			return TRUE;
		else 
			return FALSE;
	}
};

