struct T_FSRC_KEY
{
	UINT ElemK;
	UINT DgnLcomK;
	int  nPos;  // 0:I, 1:M, 2:J
	operator unsigned long() {return (DgnLcomK<<24) + (ElemK<<1) + nPos; }

	BOOL operator==(const T_FSRC_KEY& rKey) const
	{
		if(ElemK == rKey.ElemK && DgnLcomK == rKey.DgnLcomK && nPos == rKey.nPos) 
			return TRUE;
		else 
			return FALSE;
	}
};

struct T_FSRC_BASE
{
	BOOL bCheck;
	UINT LcomK;
	UINT DgnLcomK;
	int iMax; //MIN=0, MAX=1
	// Add by GAY. MNET:2683. ('07.05.12). Load Component Type (1~7:FX,FY,FZ,MX,MY,MZ,Stress).
	int iCompType;
	double dFxx, dFyy, dFzz;
	double dMux, dMuy, dMuz;
	void Initialize()
	{
		bCheck = FALSE;
		LcomK = 0;
		DgnLcomK = 0;
		iMax = 0;
		iCompType = 0;
		dFxx = dFyy = dFzz = 0.0;
		dMux = dMuy = dMuz = 0.0;
	}
};

struct T_FSRC_D
{
	UINT ElemK;
	BOOL bCheck;
	CArray<T_FSRC_BASE,T_FSRC_BASE> FsrcBase[5]; //I, 1/4, M, 3/4, J
	void Initialize()
	{
		ElemK = 0;
		bCheck = FALSE;
		for(int i = 0; i < 5; i++)
		{
			FsrcBase[i].RemoveAll();
		}
	}

	T_FSRC_D()
	{
	}
	T_FSRC_D(T_FSRC_D& src)
	{
		*this = src;
	}
	T_FSRC_D& operator=(T_FSRC_D& src)
	{
		ElemK = src.ElemK;
		bCheck = src.bCheck;
		for(int i=0; i<5; i++) FsrcBase[i].Copy(src.FsrcBase[i]);
		return *this;
	}
};

struct T_FSRC_D_RW
{
	UINT ElemK;
	BOOL bCheck;
	int nNumFsrcBase[5];
	void Initialize()
	{
		ElemK = 0;
		bCheck = FALSE;
		for(int i=0; i<5; i++) nNumFsrcBase[i] = 0;
	}
	void GetFsrc(T_FSRC_D& rData)
	{        
	}
	void SetFsrc(const T_FSRC_D& rData)
	{
		ElemK = rData.ElemK;
		bCheck = rData.bCheck;
		for(int i=0; i<5; i++)  nNumFsrcBase[i] = (int)rData.FsrcBase[i].GetSize();
	}  
};

