struct T_RTOW_D
{
	BOOL bCheck;
// dblCodeRatio : RSx, RSy, RSz, RBy, RBz, RComb
// RSy;  // Fyy에 대한 Ratio
// RSz;  // Fzz에 대한 Ratio
	double dblCodeRatio[6];

	int nCheckResult;    // 1=OK  2=NG
	int nResultPosition; // 0,1,2,3,4  , Truss는 0,4
	double res_Pa;   // res_Pos위치의 축력
	double res_fa;   // axial computed stress
	double res_Fa;   // axial allowable stress

	// Set Bolt Result Data.
	double  res_FyBolt;
	double  res_FuBolt;
	int     res_iJointType;
	int     res_BoltArray;
	CString res_BoltMatNa;
	CString res_BoltNa;
	int     res_BoltNum;

	double  res_BoltTa;
	double  res_BoltVa;
	double  res_BoltSa;
	double  res_MemSa;

	double  res_BoltSF;
	double  res_MemSF;

	void Initialize()
	{
		bCheck=FALSE;
		for(int i=0; i<6; i++)dblCodeRatio[i]=0.;
		nCheckResult=0;
		nResultPosition=0;
		res_Pa=0.;   // res_Pos위치의 축력
	
		res_fa=0.;   // axial computed stress
		res_Fa=0.;   // axial allowable stress

		res_FyBolt = 0.0;
		res_FuBolt = 0.0;
		res_iJointType = 0;
		res_BoltArray = 0;
		res_BoltMatNa.Empty();
		res_BoltNa.Empty();
		res_BoltNum = 0;

		res_BoltTa = 0.0;
		res_BoltVa = 0.0;
		res_BoltSa = 0.0;
		res_MemSa = 0.0;

		res_BoltSF = 0.0;
		res_MemSF = 0.0;
	}
};

struct T_RTOW_D_CH
{
	BOOL bCheck;
// dblCodeRatio : RSx, RSy, RSz, RBy, RBz, RComb
// RSy;  // Fyy에 대한 Ratio
// RSz;  // Fzz에 대한 Ratio
	double dblCodeRatio[6];

	int nCheckResult;    // 1=OK  2=NG
	int nResultPosition; // 0,1,2,3,4  , Truss는 0,4
	double res_Pa;   // res_Pos위치의 축력
	double res_fa;   // axial computed stress
	double res_Fa;   // axial allowable stress

	// Set Bolt Result Data.
	double  res_FyBolt;
	double  res_FuBolt;
	int     res_iJointType;
	int     res_BoltArray;
	char    res_BoltMatNa[16];
	char    res_BoltNa[16];
	int     res_BoltNum;

	double  res_BoltTa;
	double  res_BoltVa;
	double  res_BoltSa;
	double  res_MemSa;

	double  res_BoltSF;
	double  res_MemSF;

	void ConvertToString(T_RTOW_D& rData)
	{
		rData.bCheck = bCheck;
		memcpy(rData.dblCodeRatio, dblCodeRatio, sizeof(dblCodeRatio));
		rData.nCheckResult = nCheckResult;
		rData.nResultPosition = nResultPosition;
		rData.res_Pa = res_Pa;   // res_Pos위치의 축력
	
		rData.res_fa = res_fa;   // axial computed stress
		rData.res_Fa = res_Fa;   // axial allowable stress

		rData.res_FyBolt = res_FyBolt;
		rData.res_FuBolt = res_FuBolt;
		rData.res_iJointType = res_iJointType;
		rData.res_BoltArray = res_BoltArray;
		ConvertCharStr(res_BoltMatNa, rData.res_BoltMatNa, sizeof(res_BoltMatNa));
		ConvertCharStr(res_BoltNa, rData.res_BoltNa, sizeof(res_BoltNa));
		rData.res_BoltNum = res_BoltNum;

		rData.res_BoltTa = res_BoltTa;
		rData.res_BoltVa = res_BoltVa;
		rData.res_BoltSa = res_BoltSa;
		rData.res_MemSa = res_MemSa;

		rData.res_BoltSF = res_BoltSF;
		rData.res_MemSF = res_MemSF;
	}
	void ConvertToChar(T_RTOW_D& rData)
	{
		bCheck = rData.bCheck;
		memcpy(dblCodeRatio, rData.dblCodeRatio, sizeof(dblCodeRatio));
		nCheckResult = rData.nCheckResult;
		nResultPosition = rData.nResultPosition;
		res_Pa = rData.res_Pa;   // res_Pos위치의 축력
	
		res_fa = rData.res_fa;   // axial computed stress
		res_Fa = rData.res_Fa;   // axial allowable stress

		res_FyBolt = rData.res_FyBolt;
		res_FuBolt = rData.res_FuBolt;
		res_iJointType = rData.res_iJointType;
		res_BoltArray = rData.res_BoltArray;
		ConvertStrChar(rData.res_BoltMatNa, res_BoltMatNa, sizeof(res_BoltMatNa));
		ConvertStrChar(rData.res_BoltNa, res_BoltNa, sizeof(res_BoltNa));
		res_BoltNum = rData.res_BoltNum;

		res_BoltTa = rData.res_BoltTa;
		res_BoltVa = rData.res_BoltVa;
		res_BoltSa = rData.res_BoltSa;
		res_MemSa = rData.res_MemSa;

		res_BoltSF = rData.res_BoltSF;
		res_MemSF = rData.res_MemSF;
	}
};

