struct T_HDCT_RW    // 읽기 쓰기용 구조체
{
	T_HDCT_FXD FData;
	T_DATA_VXD VData;
	void Set(T_HDCT_D& crData)
	{
		FData.Set(crData);
		if (FData.aItem.nCount > 0)
		{
			CArray<T_HDCT_BASE_CH, T_HDCT_BASE_CH&> aItemCH;
			aItemCH.SetSize(FData.aItem.nCount);
			for (int i = 0; i < (int)FData.aItem.nCount; i++)
				aItemCH[i].ConvertToChar(crData.aItem[i]);

			int nSize = FData.aItem.nCount*sizeof(T_HDCT_BASE_CH);
			VData.SetSize(nSize);
			VData.Write(aItemCH.GetData(), nSize);
		}
		else VData.SetSize(0);  // 꼭 필요
	}
	BOOL Get(T_HDCT_D& rData)
	{
		if (!FData.Get(rData)) return FALSE;
		if (FData.aItem.nCount > 0)
		{
			CArray<T_HDCT_BASE_CH, T_HDCT_BASE_CH&> aItemCH;
			aItemCH.SetSize(FData.aItem.nCount);

			if (!VData.PrepareRead()) return FALSE;
			ASSERT(VData.nSize == FData.aItem.nCount*sizeof(T_HDCT_BASE_CH));
			if (!VData.Read(aItemCH.GetData(), VData.nSize)) return FALSE;

			for (int i = 0; i < (int)FData.aItem.nCount; i++)
				aItemCH[i].ConvertToString(rData.aItem[i]);
		}
		return TRUE;
	}
};

