struct T_HDGP_D
{
	T_HDGP_BASE Param[4];   // 0:Steel Column, 1:SRC Column, 2:Beam, 3:Brace
	double dAllowRatio;
	int nSameSection; // 0:No Limit, 1:상부<하부, 2:상부=하부
	int nBuiltUp; // 0:External, 1:Internal
	CArray<double, double> aPlateThk;
	T_HDGP_D() {}
	T_HDGP_D(const T_HDGP_D& crData) { *this = crData; }
	T_HDGP_D& operator=(const T_HDGP_D& crData)
	{
		for (int i = 0; i < 4; i++)
			Param[i] = crData.Param[i];
		dAllowRatio = crData.dAllowRatio;
		nSameSection = crData.nSameSection;
		nBuiltUp = crData.nBuiltUp;
		aPlateThk.Copy(crData.aPlateThk);
		return *this;
	}
	void Initialize()
	{
		for (int i = 0; i < 4; i++) Param[i].Initialize();
		dAllowRatio = 0.995;
		nSameSection = 0;
		nBuiltUp = 0;
		aPlateThk.RemoveAll();
	}
};

struct T_HDGP_FXD   // 고정 길이 : 크기를 이용해 버전 구분
{
	T_HDGP_BASE_FXD Param[4];
	double dAllowRatio;
	int nSameSection;
	int nBuiltUp;
	T_VAR_VXD aPlateThk;
	void Set(T_HDGP_D& rData)
	{
		for (int i = 0; i < 4; i++)
			Param[i].Set(rData.Param[i]);
		dAllowRatio = rData.dAllowRatio;
		nSameSection = rData.nSameSection;
		nBuiltUp = rData.nBuiltUp;
		aPlateThk.SetCount((int)rData.aPlateThk.GetSize());
	}
	BOOL Get(T_HDGP_D& rData)
	{
		if (aPlateThk.nCount != ~aPlateThk.rCount) return FALSE;
		for (int i = 0; i < 4; i++)
			if (!Param[i].Get(rData.Param[i])) return FALSE;
		rData.dAllowRatio = dAllowRatio;
		rData.nSameSection = nSameSection;
		rData.nBuiltUp = nBuiltUp;
		rData.aPlateThk.SetSize(aPlateThk.nCount);
		return TRUE;
	}
};

struct T_HDGP_UDRD_D
{
	T_HDGP_D data;
};
