#define HASHSIZEHDGP 1

struct T_HDGP_RW    // 읽기 쓰기용 구조체
{
	T_HDGP_FXD FData;
	T_DATA_VXD VData;
	UINT GetSizeVXD(T_HDGP_D& crData)
	{
		CStringA csSectDB_mbcs;
		UINT nSize = 0;
		for (int i = 0; i < 4; i++)
		{
			csSectDB_mbcs = crData.Param[i].csSectDB;
			nSize += csSectDB_mbcs.GetLength();
		}
		nSize += (int)crData.aPlateThk.GetSize()*sizeof(double);
		return nSize;
	}
	void Set(T_HDGP_D& crData)
	{
		CStringA csSectDB_mbcs;

		FData.Set(crData);
		UINT nTotalSize = GetSizeVXD(crData);
		VData.SetSize(nTotalSize);
		for (int i = 0; i < 4; i++)
		{
			csSectDB_mbcs = crData.Param[i].csSectDB;
			VData.Write(csSectDB_mbcs.GetBuffer(0), FData.Param[i].csSectDB.nCount);
			csSectDB_mbcs.ReleaseBuffer();
			crData.Param[i].csSectDB.ReleaseBuffer();
		}
		VData.Write(crData.aPlateThk.GetData(), FData.aPlateThk.nCount*sizeof(double));
	}
	BOOL Get(T_HDGP_D& rData)
	{
		if (!FData.Get(rData)) return FALSE;
		if (!VData.PrepareRead()) return FALSE;
		UINT nSize;
		for (int i = 0; i < 4; i++)
		{
			nSize = FData.Param[i].csSectDB.nCount;
			CStringA csSectDB_mbcs;
			if (!VData.Read(csSectDB_mbcs.GetBufferSetLength(nSize), nSize)) return FALSE;
			csSectDB_mbcs.ReleaseBuffer(nSize);
			rData.Param[i].csSectDB = csSectDB_mbcs;
		}
		if (!VData.Read(rData.aPlateThk.GetData(), FData.aPlateThk.nCount*sizeof(double))) return FALSE;
		return TRUE;
	}
};

