struct T_HDPP_D
{
	BOOL bChkDgn;
	BOOL bGlobal;
	CString csShape;
	T_HDGP_BASE Param;
	double dAllowRatio;
	int nSameSection; // 0:No Limit, 1:상부<하부, 2:상부=하부
	int    nBuiltUp;  // 0:External, 1:Internal
	CArray<double, double> aPlateThk;

	T_HDPP_D() {}
	T_HDPP_D(const T_HDPP_D& crData) { *this = crData; }
	T_HDPP_D& operator=(const T_HDPP_D& crData)
	{
		bChkDgn = crData.bChkDgn;
		bGlobal = crData.bGlobal;
		csShape = crData.csShape;
		Param = crData.Param;
		dAllowRatio = crData.dAllowRatio;
		nSameSection = crData.nSameSection;
		nBuiltUp = crData.nBuiltUp;
		aPlateThk.Copy(crData.aPlateThk);
		return *this;
	}
	void Initialize()
	{
		bChkDgn = FALSE;
		bGlobal = TRUE;
		csShape.Empty();
		Param.Initialize();
		dAllowRatio = 0.995;
		nSameSection = 0;
		nBuiltUp = 0;
		aPlateThk.RemoveAll();
	}
};

struct T_HDPP_FXD   // 고정 길이 : 크기를 이용해 버전 구분
{
	T_HDPP_K Key;
	BOOL bChkDgn;
	BOOL bGlobal;
	T_VAR_VXD csShape;
	T_HDGP_BASE_FXD Param;
	double dAllowRatio;
	int nSameSection;
	int nBuiltUp;
	T_VAR_VXD aPlateThk;
	void Set(T_HDPP_K Key, T_HDPP_D& rData)
	{
		this->Key = Key;
		bChkDgn = rData.bChkDgn;
		bGlobal = rData.bGlobal;
		csShape.SetCount(rData.csShape.GetLength());
		Param.Set(rData.Param);
		dAllowRatio = rData.dAllowRatio;
		nSameSection = rData.nSameSection;
		nBuiltUp = rData.nBuiltUp;
		aPlateThk.SetCount((int)rData.aPlateThk.GetSize());
	}
	BOOL Get(T_HDPP_K& rKey, T_HDPP_D& rData)
	{
		if (csShape.nCount != ~csShape.rCount) return FALSE;
		if (aPlateThk.nCount != ~aPlateThk.rCount) return FALSE;
		if (!Param.Get(rData.Param)) return FALSE;
		rKey = Key;
		rData.bChkDgn = bChkDgn;
		rData.bGlobal = bGlobal;
		rData.csShape.Empty();
		rData.dAllowRatio = dAllowRatio;
		rData.nSameSection = nSameSection;
		rData.nBuiltUp = nBuiltUp;
		rData.aPlateThk.RemoveAll();
		return TRUE;
	}
};

