struct T_HDPP_RW    // 읽기 쓰기용 구조체
{
	T_HDPP_FXD FData;
	T_DATA_VXD VData;
	UINT GetSizeVXD(T_HDPP_D& crData)
	{
		UINT nSize = 0;
		nSize += crData.csShape.GetLength();
		nSize += crData.Param.csSectDB.GetLength();
		nSize += (int)crData.aPlateThk.GetSize()*sizeof(double);
		return nSize;
	}
	void Set(T_HDPP_K Key, T_HDPP_D& crData)
	{
		FData.Set(Key, crData);
		UINT nTotalSize = GetSizeVXD(crData);
		VData.SetSize(nTotalSize);
		VData.Write(crData.csShape.GetBuffer(0), FData.csShape.nCount);
		crData.csShape.ReleaseBuffer();
		VData.Write(crData.Param.csSectDB.GetBuffer(0), FData.Param.csSectDB.nCount);
		crData.Param.csSectDB.ReleaseBuffer();
		VData.Write(crData.aPlateThk.GetData(), FData.aPlateThk.nCount*sizeof(double));
	}
	BOOL Get(T_HDPP_K& rKey, T_HDPP_D& rData)
	{
		if (!FData.Get(rKey, rData)) return FALSE;
		if (!VData.PrepareRead()) return FALSE;
		UINT nSize = FData.csShape.nCount;
		if (!VData.Read(rData.csShape.GetBufferSetLength(nSize), nSize)) return FALSE;
		rData.csShape.ReleaseBuffer(nSize);
		nSize = FData.Param.csSectDB.nCount;
		if (!VData.Read(rData.Param.csSectDB.GetBufferSetLength(nSize), nSize)) return FALSE;
		rData.Param.csSectDB.ReleaseBuffer(nSize);
		rData.aPlateThk.SetSize(FData.aPlateThk.nCount);
		if (!VData.Read(rData.aPlateThk.GetData(), FData.aPlateThk.nCount*sizeof(double))) return FALSE;
		return TRUE;
	}
};

