struct T_SLCF_D
{
	double		dDLoadFactor;
	double		dVLoadFactor;
	double		dSDS;
	T_SOSF_DT aLoadPattern; 
	void Initialize()
	{
		dDLoadFactor = 0.2;
		dVLoadFactor = 0.2;
		dSDS				 = 0.0;
		aLoadPattern.RemoveAll();
	}
	void Initialize(const CString& strCode)
	{
		Initialize();

		if (strCode == STLCODE_NSCP_2015_ASD || strCode == STLCODE_NSCP_2015_LRFD ||
			strCode == CONCODE_NSCP_2015)
		{
			dDLoadFactor = 0.5;
			dVLoadFactor = 0.7;
			dSDS = 0.4;
		}		
	}
	T_SLCF_D()
	{
	}
	T_SLCF_D(T_SLCF_D& src)
	{
		*this = src;
	}
	T_SLCF_D& operator=(T_SLCF_D& src)
	{
		dDLoadFactor = src.dDLoadFactor;
		dVLoadFactor = src.dVLoadFactor;
		dSDS				 = src.dSDS;
		aLoadPattern.Copy(src.aLoadPattern);
		return *this;
	}
};
