// Set Load Case for Wind Direction
struct T_LCWD_BASE		
{ 
	BOOL      bAuto;
	int       nBuildingType;
	T_STLD_K	StldKAlong;
	T_STLD_K	StldKAcross;
	T_STLD_K	StldKTorsion;
	double	  dFactorGD;
	double	  dFactorK;

	void Initialize()
	{
		bAuto=FALSE;
		nBuildingType = 1;
		StldKAlong    = 0;
		StldKAcross   = 0;
		StldKTorsion  = 0;
		dFactorGD     = 2.2;
		dFactorK      = 0.8;
	}

	BOOL operator == (const T_LCWD_BASE& rLcwdBase) const 
	{
		if(rLcwdBase.nBuildingType!= nBuildingType ) return FALSE;
		if(rLcwdBase.StldKAlong   != StldKAlong ) return FALSE;
		if(rLcwdBase.StldKAcross  != StldKAcross) return FALSE;
		if(rLcwdBase.StldKTorsion != StldKTorsion) return FALSE;
		if(fabs(rLcwdBase.dFactorGD-dFactorGD) > 1.0E-9 ) return FALSE;
		if(fabs(rLcwdBase.dFactorK -dFactorK ) > 1.0E-9 ) return FALSE;
		return TRUE;
	}
};

