struct T_RCBE_D
{
	int iRhoStand; // 최소철근비 산출기준(0=보 , 1=슬래브) default=0
	int iServCond; // 사용성 검토조건 (0=건조환경1, 1=건조환경2, 2=습윤환경1, 3=습윤환경2, 4=부식성환경, 5= 고부식성환경 ) default=0
	BOOL bPosi[3]; //0=I단, 1=J단 2=Mid
	BOOL bStirrup; //허용균열폭 산정기 전단철근 포함.
	double dDt;    // Design하기 위한 철근 도심의 임의 위치 .(Top에서)
	double dDb;    // Design하기 위한 철근 도심의 임의 위치 .(Bot에서)
	CString strRemark;   // 비고
	void Initialize()
	{
		int iRhoStand=0;
		int iServCond=0;
		for(int i=0;i<3;i++)
			bPosi[i]=0;
		bStirrup=FALSE; 
		dDt=0.;
		dDb=0.;
		strRemark=_T("");   // 비고
	}
};
struct T_RCBE_D_CH
{
	int iRhoStand; // 최소철근비 산출기준(0=보 , 1=슬래브) default=0
	int iServCond; // 사용성 검토조건 (0=건조환경1, 1=건조환경2, 2=습윤환경1, 3=습윤환경2, 4=부식성환경, 5= 고부식성환경 ) default=0
	BOOL bPosi[3]; //0=I단, 1=J단 2=Mid
	BOOL bStirrup; //허용균열폭 산정기 전단철근 포함.
	double dDt;    // Design하기 위한 철근 도심의 임의 위치 .(Top에서)
	double dDb;    // Design하기 위한 철근 도심의 임의 위치 .(Bot에서)
	char strRemark[40];   // 비고
	void ConvertToString(T_RCBE_D& rData)
	{
		rData.iRhoStand = iRhoStand;
		rData.iServCond = iServCond;
		for(int i=0;i<3;i++)
		{
			rData.bPosi[i]=bPosi[i];
		}
		rData.bStirrup=bStirrup; 
		rData.dDt=dDt;    
		rData.dDb=dDb;    
		ConvertCharStr(strRemark, rData.strRemark, sizeof(strRemark));
	}
	void ConvertToChar(T_RCBE_D& rData)
	{
		iRhoStand = rData.iRhoStand;
		iServCond = rData.iServCond;
		for(int i=0;i<3;i++)
		{
			bPosi[i]=rData.bPosi[i];
		}
		bStirrup=rData.bStirrup; 
		dDt=rData.dDt;    
		dDb=rData.dDb;    
		ConvertStrChar(rData.strRemark, strRemark, sizeof(strRemark));
	}
};
