	CString strTopBarNa2[3][T_CPBE_LAYER]; // Top Size2 철근 직경
	CString strBotBarNa1[3][T_CPBE_LAYER]; // Bottom Size1 철근 직경
	CString strBotBarNa2[3][T_CPBE_LAYER]; // Bottom Size2 철근 직경
