	double  dSubBarDist[3];  // 전단철근 간격
	CString strSubBarNa[3]; // 전단철근 직경
	BOOL    bChkSubBar[3];  // 전단검토 여부 default=TRUE      (8.4.2 추가)
	double  dSubBarAngle[3];// 전단철근 기울기 (default=90도)  (8.4.2 추가)


	void Initialize()
	{
		bNum = TRUE;
		int i,j;
		for(i = 0; i<3; i++)
		{
			dSubBarNum[i] = 0.0;
			dSubBarDist[i] = 0.0;
			strSubBarNa[i] = _T("");
			bChkSubBar[i] = FALSE;
			dSubBarAngle[i] = 0.0;

			for(j=0; j<T_CPBE_LAYER; j++)
			{
				dDt[i][j] = 0.0;
				dDb[i][j] = 0.0;
				dTopBarNum[i][j] = 0.0;
				dBotBarNum[i][j] = 0.0;
				dTopBarCTC[i][j] = 0.0;
				dBotBarCTC[i][j] = 0.0;
				strTopBarNa1[i][j] = _T("");
				strTopBarNa2[i][j] = _T("");
				strBotBarNa1[i][j] = _T("");
				strBotBarNa2[i][j] = _T("");
			}
		}  
	}

