struct T_RBTE_D
{
	int iCenterType;//좌표중심 (0:도심, 1:좌하단) (default = 0)
	BOOL bIJBothMain;
	BOOL bIJBothShear;
	CArray<T_RBTE_MABR, T_RBTE_MABR&> arMainRebar[3];
	T_RBTE_SHBR ShearRebar[3];

	T_RBTE_D() {}
	T_RBTE_D(const T_RBTE_D& crData) { *this = crData; }
	T_RBTE_D& operator=(const T_RBTE_D& crData)
	{
		iCenterType=crData.iCenterType;
		bIJBothMain=crData.bIJBothMain;
		bIJBothShear=crData.bIJBothShear;
		arMainRebar[0].Copy(crData.arMainRebar[0]);
		arMainRebar[1].Copy(crData.arMainRebar[1]);
		arMainRebar[2].Copy(crData.arMainRebar[2]);
		ShearRebar[0]=crData.ShearRebar[0];
		ShearRebar[1]=crData.ShearRebar[1];
		ShearRebar[2]=crData.ShearRebar[2];
		return *this;
	}
	void Initialize()
	{
		iCenterType=0;
		bIJBothMain=TRUE;
		bIJBothShear=TRUE;
		arMainRebar[0].RemoveAll();
		arMainRebar[1].RemoveAll();
		arMainRebar[2].RemoveAll();
		ShearRebar[0].Initialize();
		ShearRebar[1].Initialize();
		ShearRebar[2].Initialize();
	}
};

