// Rating Case 입력을 위한 구조체

#define T_BLRC_K unsigned int


struct T_BLRC_D
{
	int iLimitState; // 0=ServiceLimit State, 1=Strength  Limit State ,  0,1만 허용, 1번참조
	CString RatingCaseName;   //5번참조
	CString Description;          // 5번참조
	T_LCOM_BASE PrimaryVeh;    // Primary vehicle      4번참조
	T_LCOM_BASE AdjacentVeh;  // Adjacent vehicle      4번참조
	T_RTLD_D RateLoad[7]; // DC, DW, T, SEC, Permanet, User, Temp.Gradient...
	int iEvaluation; // 0: Design Load 1: Legal Load / Permit Load  2: Permit Load (LRFR19)
	void Initialize()
	{
		iLimitState=0;
		RatingCaseName=_T("");
		Description=_T("");
		PrimaryVeh.LoadCaseKey=0;
		PrimaryVeh.Factor=1.;
		AdjacentVeh.AnalType=0;  // D_LCOM_???
		AdjacentVeh.LoadCaseKey=0;
		AdjacentVeh.Factor=1.;
		iEvaluation=0;
		for(int i=0;i<7;i++)
			RateLoad[i].Initialize(i+1);
	}
	T_BLRC_D& operator=(const T_BLRC_D& crData)
	{
		iLimitState=crData.iLimitState;
		RatingCaseName=crData.RatingCaseName;
		Description=crData.Description;
		PrimaryVeh=crData.PrimaryVeh;
		AdjacentVeh=crData.AdjacentVeh;
		for(int i=0;i<7;i++)
			RateLoad[i]=crData.RateLoad[i];
		iEvaluation=crData.iEvaluation;
		return *this;
	}  
	T_BLRC_D(const T_BLRC_D& crData) { *this = crData; }
	T_BLRC_D() {}
};
