// KR DGN RC Rating - Global Parameter
#define T_RPAC_K unsigned int
struct T_RPAC_D_880
{
	BOOL bPrintParm[3];     // default=FALSE -> 기준별 다름
	double dDgnLiveLoad;    // 설계활하중. default = 24, Boundary >0
	int nSurveyMeth;        // 0:처짐 1:변형률
	CString strDgnLiveLoad; // 설계활하중 이름
};
struct T_RPAC_D
{   
	BOOL bPrintParm[3];     // default=FALSE -> 기준별 다름
	double dDgnLiveLoad;    // 설계활하중. default = 24, Boundary >0
	int nSurveyMeth;        // 0:처짐 1:변형률
	CString strDgnLiveLoad; // 설계활하중 이름
	BOOL bUserInputData;		// LSD기준 사용자 입력 데이터
	// 재료저항계수 (LSD)
	double dPhi_c[3];				//conc,	 0:극한 1:극단 2:사용
	double dPhi_s[3];				//rebar, 0:극한 1:극단 2:사용
	BOOL bCheckCofLongTerm; //Coefficient for Long Term Effects 사용여부
	double	dAlphacc;				//Alpha_cc

	T_RPAC_D() {}
	T_RPAC_D(const T_RPAC_D& src) { *this = src; }
	T_RPAC_D& operator=(const T_RPAC_D& src)
	{
		for (int i=0 ; i<3 ; ++i) bPrintParm[i] = src.bPrintParm[i];
		dDgnLiveLoad = src.dDgnLiveLoad;
		nSurveyMeth = src.nSurveyMeth;
		strDgnLiveLoad = src.strDgnLiveLoad;
		bUserInputData = src.bUserInputData;
		for (int j=0 ; j<3 ; ++j) dPhi_c[j]	 = src.dPhi_c[j];
		for (int k=0 ; k<3 ; ++k) dPhi_s[k]	 = src.dPhi_s[k];
		bCheckCofLongTerm = src.bCheckCofLongTerm;
		dAlphacc = src.dAlphacc;
		return *this;
	}
	void Convert880(T_RPAC_D_880& rData)
	{
		for (int i=0 ; i<3 ; ++i) bPrintParm[i] = FALSE;
		dDgnLiveLoad = 24.0;
		nSurveyMeth = 0;
		strDgnLiveLoad = _T("DB");
		bUserInputData = FALSE;
		memset(dPhi_c, NULL, sizeof(dPhi_c));
		memset(dPhi_s, NULL, sizeof(dPhi_s));
		bCheckCofLongTerm = FALSE;
		dAlphacc = 0.85;
	}

	void Initialize()
	{
		for (int i=0 ; i<3 ; ++i) bPrintParm[i] = FALSE;
		dDgnLiveLoad = 24.0;
		nSurveyMeth = 0;
		strDgnLiveLoad = _T("DB");
		bUserInputData = FALSE;
		memset(dPhi_c, NULL, sizeof(dPhi_c));
		memset(dPhi_s, NULL, sizeof(dPhi_s));
		bCheckCofLongTerm = FALSE;
		dAlphacc = 0.85;
	}

	void Initialize(int iCode)
	{
		Initialize();

		switch(iCode)
		{
		case KSCE_USD10_RC_RATING:
			dDgnLiveLoad = 24.0;
			strDgnLiveLoad = _T("DB");
			break;
		case KSCE_RAIL_USD11_RC_RATING:
			dDgnLiveLoad = 22.0;
			strDgnLiveLoad = _T("LS");
			break;
		case KSCE_LSD15_RC_RATING:
			dDgnLiveLoad = 510.0;
			strDgnLiveLoad = _T("KL");
			break;
		}
	}

	void Set_RC_Rating_AnnexData_LSD()
	{
		dPhi_c[0]  = 0.65; //conc, 0:극한 1:극단 2:사용
		dPhi_s[0]  = 0.90; //철근, 0:극한 1:극단 2:사용
		dPhi_c[1]  = 0.85; 
		dPhi_s[1]  = 1.0;  
		dPhi_c[2]  = 1.0; 
		dPhi_s[2]  = 1.0; 
	}
};

struct T_RPAC_D_CH_880
{
	BOOL bPrintParm[3];     // default=TRUE -> 기준별 다름
	double dDgnLiveLoad;    // 설계활하중. default = 24, Boundary >0
	int nSurveyMeth;        // 0:처짐 1:변형률
	char strDgnLiveLoad[16]; // 설계활하중 이름
};

struct T_RPAC_D_CH
{
	BOOL bPrintParm[3];     // default=TRUE -> 기준별 다름
	double dDgnLiveLoad;    // 설계활하중. default = 24, Boundary >0
	int nSurveyMeth;        // 0:처짐 1:변형률
	char strDgnLiveLoad[16]; // 설계활하중 이름
	BOOL bUserInputData;		// LSD기준 사용자 입력 데이터
	// 재료저항계수 (LSD)
	double dPhi_c[3];				//conc,	 0:극한 1:극단 2:사용
	double dPhi_s[3];				//rebar, 0:극한 1:극단 2:사용
	BOOL bCheckCofLongTerm; //Coefficient for Long Term Effects 사용여부
	double	dAlphacc;				//Alpha_cc

	void ConvertToString(T_RPAC_D& rData)
	{
		for (int i=0 ; i<3 ; ++i) rData.bPrintParm[i] = bPrintParm[i];
		rData.dDgnLiveLoad = dDgnLiveLoad;
		rData.nSurveyMeth  = nSurveyMeth;	
		ConvertCharStr(strDgnLiveLoad, rData.strDgnLiveLoad, sizeof(strDgnLiveLoad));
		rData.bUserInputData = bUserInputData;
		for (int j=0 ; j<4 ; ++j) rData.dPhi_c[j]	 = dPhi_c[j];
		for (int k=0 ; k<4 ; ++k) rData.dPhi_s[k]	 = dPhi_s[k];
		rData.bCheckCofLongTerm = bCheckCofLongTerm;
		rData.dAlphacc = dAlphacc;
	}
	void ConvertToChar(T_RPAC_D& rData)
	{
		for (int i=0 ; i<3 ; ++i) bPrintParm[i] = rData.bPrintParm[i];
		dDgnLiveLoad = rData.dDgnLiveLoad;
		nSurveyMeth = rData.nSurveyMeth;
		ConvertStrChar(rData.strDgnLiveLoad, strDgnLiveLoad, sizeof(strDgnLiveLoad));
		bUserInputData = rData.bUserInputData;
		for (int j=0 ; j<4 ; ++j) dPhi_c[j]	 = rData.dPhi_c[j];
		for (int k=0 ; k<4 ; ++k) dPhi_s[k]	 = rData.dPhi_s[k];
		bCheckCofLongTerm = rData.bCheckCofLongTerm;
		dAlphacc = rData.dAlphacc;
	}
	void Convert880(T_RPAC_D_CH_880& rData)
	{
		for (int i=0 ; i<3 ; ++i) bPrintParm[i] = rData.bPrintParm[i];
		dDgnLiveLoad = rData.dDgnLiveLoad;
		nSurveyMeth = rData.nSurveyMeth;
		memcpy(strDgnLiveLoad, rData.strDgnLiveLoad, sizeof(strDgnLiveLoad));
		bUserInputData = FALSE;
		dPhi_c[0]  = 0.65; //conc, 0:극한 1:극단 2:사용
		dPhi_c[1]  = 0.85; 
		dPhi_c[2]  = 1.0; 
		dPhi_s[0]  = 0.90; //철근, 0:극한 1:극단 2:사용
		dPhi_s[1]  = 1.0;  
		dPhi_s[2]  = 1.0;  
		bCheckCofLongTerm = FALSE;
		dAlphacc = 0.85;
	}
};

