struct T_RPAS_D
{   
	int    nSurveyMeth;     // 0:처짐 1:변형률
	double dDgnLiveLoad;    // 설계활하중. default = 24, Boundary >0
	BOOL   bPrintParm[5];   // default=TRUE -> 기준별 다름
	CString strDgnLiveLoad; // 설계활하중 이름

	double dSystemFactor;   // System Facotr, default=1.0, (Check: 0 이상)
	BOOL   bStrength;
	double dPhi_y;          // Resistance Factor For Yilding
	double dPhi_u;          // Resistance Factor For fracture
	double dPhi_c;          // Resistance Factor For axial comp
	double dPhi_f;          // Resistance Factor For flexure
	double dPhi_v;          // Resistance Factor For shear
	double dPhi_se;         // Resistance Factor For shear connector
	double dPhi_b;          // Resistance Factor For bearing
	int    nGirderType;     // Girder Type 0:Single, 1:Multi
	BOOL   bConsiderTorsion; 
	int    nBridgeType;     // 0:Straight, 1:Curve

	BOOL bStrengthOption[4]; //(v950) bStrengthOption[3] -> bStrengthOption[4]

	BOOL   bService;
	int    nServCalcType;   // 0:Auto, 1:User
	double dDgnLoadComp;
	double dDgnLoadTens;
	double dLegalLoadComp;
	double dLegalLoadTens;

	BOOL bFatigue;
	int nMeasurement;       // 0:Strain, 1:Displacement
	BOOL bUserInputData;	//(v900) LSD기준 사용자 입력 데이터

	int nFatigueLife;       //(v905) 0:Infinite, 1:Infinite + finite
	double dCurAge_a;       //(v905) Current Age Detail
	double dAdTTSL_g;       //(v905) Expected Annual Growth Rate of ADTTSL_g
	double dAdTTSL_P;       //(v905) Average Number of Truck per Day - (ADTTSL)Present
	double dAdTTSL_0;       //(v905) Average Number of Truck per Day - (ADTTSL)0
	double dAdTTSL_lim;     //(v905) Average Number of Truck per Day - (ADTTSL)limit
	int nFatServ_G;         //(v905) Load Path Factor(G)   0: 0.8, 1: 0.9,  2:1.0 
	int nFatServ_R;         //(v905) Redundancy Factor(R)  0: 0.9, 1: 1.0 
	int nFatServ_I;         //(v905) Important Factor(I)   0: 0.9, 1: 0.95, 2:1.0 

	T_RPAS_D() {}
	T_RPAS_D(const T_RPAS_D& src) { *this = src; }
	T_RPAS_D& operator=(const T_RPAS_D& src)
	{	
		nSurveyMeth = src.nSurveyMeth;
		dDgnLiveLoad = src.dDgnLiveLoad;
		for (int i=0 ; i<5 ; ++i) bPrintParm[i] = src.bPrintParm[i];
		strDgnLiveLoad = src.strDgnLiveLoad;

		dSystemFactor = src.dSystemFactor;
		bStrength = src.bStrength;
		dPhi_y = src.dPhi_y;
		dPhi_u = src.dPhi_u;
		dPhi_c = src.dPhi_c;
		dPhi_f = src.dPhi_f;
		dPhi_v = src.dPhi_v;
		dPhi_se = src.dPhi_se;
		dPhi_b = src.dPhi_b;
		nGirderType = src.nGirderType;
		bConsiderTorsion = src.bConsiderTorsion;
		nBridgeType = src.nBridgeType;
		bStrengthOption[0] = src.bStrengthOption[0];
		bStrengthOption[1] = src.bStrengthOption[1];
		bStrengthOption[2] = src.bStrengthOption[2];
		bStrengthOption[3] = src.bStrengthOption[3];
		
		bService = src.bService;
		nServCalcType = src.nServCalcType;
		dDgnLoadComp = src.dDgnLoadComp;
		dDgnLoadTens = src.dDgnLoadTens;
		dLegalLoadComp = src.dLegalLoadComp;
		dLegalLoadTens = src.dLegalLoadTens;
		
		bFatigue = src.bFatigue;
		nMeasurement = src.nMeasurement;
		bUserInputData = src.bUserInputData;

		nFatigueLife = src.nFatigueLife; 
		dCurAge_a    = src.dCurAge_a; 
		dAdTTSL_g    = src.dAdTTSL_g  ;        
		dAdTTSL_P    = src.dAdTTSL_P  ;        
		dAdTTSL_0    = src.dAdTTSL_0  ;        
		dAdTTSL_lim  = src.dAdTTSL_lim;      
		nFatServ_G   = src.nFatServ_G;      
		nFatServ_R   = src.nFatServ_R;      
		nFatServ_I   = src.nFatServ_I;      

		return *this;
	}
	
	void Initialize()
	{
		nSurveyMeth = 0;
		dDgnLiveLoad = 24.0;
		for (int i=0 ; i<5 ; ++i) bPrintParm[i] = TRUE;
		strDgnLiveLoad = _T("");

		dSystemFactor = 1.0;
		bStrength = TRUE;
		dPhi_y = 0.95;
		dPhi_u = 0.80; 
		dPhi_c = 0.90;
		dPhi_f = 1.00;
		dPhi_v = 1.00;
		dPhi_se = 0.85; 
		dPhi_b = 1.00; 
		nGirderType = 1;
		bConsiderTorsion = TRUE;
		nBridgeType = 0;
		bStrengthOption[0] = FALSE;
		bStrengthOption[1] = FALSE;
		bStrengthOption[2] = FALSE;
		bStrengthOption[3] = TRUE;
		
		bService = TRUE;
		nServCalcType = 0;
		dDgnLoadComp = 0.0;
		dDgnLoadTens = 0.0;
		dLegalLoadComp = 0.0;
		dLegalLoadTens = 0.0;
		
		bFatigue = TRUE;
		nMeasurement = 1;
		bUserInputData = FALSE;

		nFatigueLife = 0;
		dCurAge_a    = 48.0;
		dAdTTSL_g    = 0.01;       
		dAdTTSL_P    = 0.0;       
		dAdTTSL_0    = 200.0;       
		dAdTTSL_lim  = 1200.0;     
		nFatServ_G   = 0;    
		nFatServ_R   = 0;    
		nFatServ_I   = 0;    
	}
	void Set_STL_Rating_AnnexData_LSD()
	{
		dPhi_y = 0.95;
		dPhi_u = 0.80; 
		dPhi_c = 0.90;
		dPhi_f = 1.00;
		dPhi_v = 1.00;
		dPhi_se = 0.85; 
		dPhi_b = 1.00; 
		nGirderType = 1;
		bConsiderTorsion = TRUE;
		nBridgeType = 0;
		bStrengthOption[1] = FALSE;
		bStrengthOption[2] = FALSE;
		bStrengthOption[3] = TRUE;
	}
};

