struct T_RRPL_SUB_D_CH
{
	BOOL bNum; //개수 ,CTC default=TRUE
	double dDt[3][T_RRPL_LAYER]; // 3:I,M,J, 10:Layer     
	double dDb[3][T_RRPL_LAYER]; // Bottom에서 거리      
	double  dTopBarNum[3][T_RRPL_LAYER]; // Top 철근 개수
	double  dBotBarNum[3][T_RRPL_LAYER]; // Bottom 철근 개수
	double dTopBarCTC[3][T_RRPL_LAYER]; //Top철근 간격
	double dBotBarCTC[3][T_RRPL_LAYER]; //Bottom철근 간격
	char strTopBarNa1[3][T_RRPL_LAYER][40]; // Top Size1 철근 직경
	char strTopBarNa2[3][T_RRPL_LAYER][40]; // Top Size2 철근 직경
	char strBotBarNa1[3][T_RRPL_LAYER][40]; // Bottom Size1 철근 직경
	char strBotBarNa2[3][T_RRPL_LAYER][40]; // Bottom Size2 철근 직경
	double  dSubBarNum[3];  // 전달철근 다리수 (default=2)
	double  dSubBarDist[3];  // 전단철근 간격
	char strSubBarNa[3][40]; // 전단철근 직경
	BOOL    bChkSubBar[3];  // 전단검토 여부 default=TRUE      (8.4.2 추가)
	double  dSubBarAngle[3];// 전달철근 기울기 (default=90도)  (8.4.2 추가)
	int nTopLayer; 
	int nBotLayer; 

	void ConvertToString(T_RRPL_SUB_D& rData)
	{
		int i,j;
		rData.bNum = bNum;
		for(i = 0;i<3;i++)
		{
			rData.dSubBarNum[i]=dSubBarNum[i];
			rData.dSubBarDist[i]=dSubBarDist[i];
			rData.bChkSubBar[i]=bChkSubBar[i];
			rData.dSubBarAngle[i]=dSubBarAngle[i];
			ConvertCharStr(strSubBarNa[i],rData.strSubBarNa[i], sizeof(strSubBarNa[i]));

			for(j=0;j<T_RRPL_LAYER;j++)
			{
				rData.dTopBarCTC[i][j]=dTopBarCTC[i][j];
				rData.dBotBarCTC[i][j]=dBotBarCTC[i][j];
				rData.dDt[i][j]=dDt[i][j];
				rData.dDb[i][j]=dDb[i][j];
				rData.dTopBarNum[i][j]=dTopBarNum[i][j];
				rData.dBotBarNum[i][j]=dBotBarNum[i][j];
				ConvertCharStr(strTopBarNa1[i][j], rData.strTopBarNa1[i][j], sizeof(strTopBarNa1[i][j]));
				ConvertCharStr(strTopBarNa2[i][j], rData.strTopBarNa2[i][j], sizeof(strTopBarNa2[i][j]));
				ConvertCharStr(strBotBarNa1[i][j],rData.strBotBarNa1[i][j], sizeof(strBotBarNa1[i][j]));
				ConvertCharStr(strBotBarNa2[i][j],rData.strBotBarNa2[i][j], sizeof(strBotBarNa2[i][j]));
			}
		}
		rData.nTopLayer = nTopLayer;
		rData.nBotLayer = nBotLayer;
	}

	void ConvertToChar(T_RRPL_SUB_D& rData)
	{
		int i,j;
		bNum = rData.bNum;
		for(i = 0;i<3;i++)
		{
			dSubBarNum[i]=rData.dSubBarNum[i];
			dSubBarDist[i]=rData.dSubBarDist[i];
			bChkSubBar[i]=rData.bChkSubBar[i];
			dSubBarAngle[i]=rData.dSubBarAngle[i];
			ConvertStrChar(rData.strSubBarNa[i],strSubBarNa[i], sizeof(strSubBarNa[i]));

			for(j=0;j<T_RRPL_LAYER;j++)
			{
				dTopBarCTC[i][j]=rData.dTopBarCTC[i][j];
				dBotBarCTC[i][j]=rData.dBotBarCTC[i][j];
				dDt[i][j]=rData.dDt[i][j];
				dDb[i][j]=rData.dDb[i][j];
				dTopBarNum[i][j]=rData.dTopBarNum[i][j];
				dBotBarNum[i][j]=rData.dBotBarNum[i][j];
				ConvertStrChar(rData.strTopBarNa1[i][j], strTopBarNa1[i][j],sizeof(strTopBarNa1[i][j]));
				ConvertStrChar(rData.strTopBarNa2[i][j], strTopBarNa2[i][j],sizeof(strTopBarNa2[i][j]));
				ConvertStrChar(rData.strBotBarNa1[i][j], strBotBarNa1[i][j],sizeof(strBotBarNa1[i][j]));
				ConvertStrChar(rData.strBotBarNa2[i][j], strBotBarNa2[i][j],sizeof(strBotBarNa2[i][j]));
			}
		}

		nTopLayer = rData.nTopLayer;
		nBotLayer = rData.nBotLayer;
	}

	void Convert850(const T_RRPL_SUB_D_CH_850& rData)
	{
		int i,j;
		bNum = rData.bNum;
		for(i = 0;i<3;i++)
		{
			dSubBarNum[i]=rData.dSubBarNum[i];
			dSubBarDist[i]=rData.dSubBarDist[i];
			bChkSubBar[i]=rData.bChkSubBar[i];
			dSubBarAngle[i]=rData.dSubBarAngle[i];
			memcpy(strSubBarNa[i], rData.strSubBarNa[i], sizeof(strSubBarNa[i]));
			
			for(j=0;j<T_RRPL_LAYER;j++)
			{
				dTopBarCTC[i][j]=rData.dTopBarCTC[i][j];
				dBotBarCTC[i][j]=rData.dBotBarCTC[i][j];
				dDt[i][j]=rData.dDt[i][j];
				dDb[i][j]=rData.dDb[i][j];
				dTopBarNum[i][j]=rData.dTopBarNum[i][j];
				dBotBarNum[i][j]=rData.dBotBarNum[i][j];
				memcpy(strTopBarNa1[i][j], rData.strTopBarNa1[i][j], sizeof(strTopBarNa1[i][j]));
				memcpy(strTopBarNa2[i][j], rData.strTopBarNa2[i][j], sizeof(strTopBarNa2[i][j]));
				memcpy(strBotBarNa1[i][j], rData.strBotBarNa1[i][j], sizeof(strBotBarNa1[i][j]));
				memcpy(strBotBarNa2[i][j], rData.strBotBarNa2[i][j], sizeof(strBotBarNa2[i][j]));
			}
		}
		nTopLayer = 1;
		nBotLayer = 1;
	}
};

struct T_RRPL_D		
{
	CString	 strName;					
	CArray<T_ELEM_K, T_ELEM_K> arElemK;						
	int      nPlateMemb ; // 0:Beam 1:Wall   : 무조건  beam 						
	int      iAxisType  ; // 축방향(0=Local, 1=UCS)						
	T_NUCS_K ucsKey     ; // UCS선택시 UCS의 Key						
	int      iAnaType   ; // 절점공유요소의 평균값을 사용할 것인지 요소값을 사용하것인지 여부  (0:Element 1:Avg.Nodal) default=0			
	BOOL     bActiveOnly; // Avg.Nodal선택시 활성화된 Nodal에 대해서만 평균할지 여부						
	int      iDir       ; // 설계 방향(0=X-Dir, 1=Y-Dir)		

	T_RRPL_SUB_D Rebar;     

	void Initialize()
	{
		strName     = _T("");
		arElemK.RemoveAll();
		nPlateMemb  = 0;
		iAxisType		= 0;
		ucsKey			= 0;
		iAnaType    = 0;
		bActiveOnly = FALSE;
		iDir				= 0;

		Rebar.Initialize();
	}
	T_RRPL_D() {}
	T_RRPL_D(const T_RRPL_D& rData) { *this = rData; }
	T_RRPL_D& operator=(const T_RRPL_D& rData)
	{
		strName = rData.strName;
		arElemK.Copy(rData.arElemK);
		nPlateMemb  = rData.nPlateMemb  ;
		iAxisType		= rData.iAxisType		;
		ucsKey			= rData.ucsKey			;
		iAnaType    = rData.iAnaType    ;
		bActiveOnly = rData.bActiveOnly ;
		iDir				= rData.iDir				;
		Rebar       = rData.Rebar;

		return *this;
	}
};

struct T_RRPL_D_CH		
{
	char	   strName[40];
	CArray<T_ELEM_K, T_ELEM_K> arElemK;						
	int      nPlateMemb ; // 0:Beam 1:Wall   : 무조건  beam 						
	int      iAxisType  ; // 축방향(0=Local, 1=UCS)						
	T_NUCS_K ucsKey     ; // UCS선택시 UCS의 Key						
	int      iAnaType   ; // 절점공유요소의 평균값을 사용할 것인지 요소값을 사용하것인지 여부  (0:Element 1:Avg.Nodal) default=0			
	BOOL     bActiveOnly; // Avg.Nodal선택시 활성화된 Nodal에 대해서만 평균할지 여부						
	int      iDir       ; // 설계 방향(0=X-Dir, 1=Y-Dir)		

	T_RRPL_SUB_D_CH Rebar;   	

	void ConvertToString(T_RRPL_D& rData)
	{
		ConvertCharStr(strName, rData.strName, sizeof(strName));
		rData.arElemK.Copy(arElemK);
		rData.nPlateMemb = nPlateMemb;
		rData.iAxisType = iAxisType;
		rData.ucsKey = ucsKey;
		rData.iAnaType = iAnaType;
		rData.bActiveOnly = bActiveOnly;
		rData.iDir = iDir;
		Rebar.ConvertToString(rData.Rebar);
	}
	void ConvertToChar(T_RRPL_D& rData)
	{
		ConvertStrChar(rData.strName, strName, sizeof(strName));
		arElemK.Copy(rData.arElemK);

		nPlateMemb  = rData.nPlateMemb;
		iAxisType   = rData.iAxisType;
		ucsKey      = rData.ucsKey;
		iAnaType    = rData.iAnaType;
		bActiveOnly = rData.bActiveOnly;
		iDir        = rData.iDir;

		Rebar.ConvertToChar(rData.Rebar);
	}
};


