// Composite plate girder design

// Composite Girder Transverse Stiffener
#define T_CGTS_K T_ELEM_K
struct T_CGTS_STIF_830
{  
	BOOL   bUseStif;					 
	BOOL   bInterRigidStif;    
	BOOL   bInterNonRigidStif; 
	int    iStifNum;           
	double dht;                
	double dt;                 
	double dPitch;             
	double dDistRstif;         
	double dDistNRstif;        
	void Initialize()
	{ 
		bUseStif = TRUE;
		bInterRigidStif=FALSE;   
		bInterNonRigidStif=FALSE;
		iStifNum = 0;           
		dht = 0.0;             
		dt = 0.0;              
		dPitch = 0.0;          
		dDistRstif = 0.0;      
		dDistNRstif = 0.0;     
	}
};

struct T_CGTS_STIF
{  
	BOOL   bUseStif;					 // Use stiffener (default=TRUE)
	BOOL   bInterRigidStif;    // Intermediate rigid stiffener (default=FALSE)
	BOOL   bInterNonRigidStif; // Intermediate non-rigid stiffener (default=FALSE)
	int    iStifNum;           // Stiffener 개수(0=One stiffener, 1=Two stiffener) (default=0, boundary=0,1)
	double dht;                // ht (default=0, boundary >0, Unit:Length)
	double dt;                 // stiffener 두께. (default=0, boundary >0, Unit:Length)
	double dPitch;             // Rigid striffener pitch (default=0, boundary >0, Unit:Length)
	double dDistRstif;         // distance from rigid stiffener (default=0, boundary >0, Unit:Length) 
	double dDistNRstif;        // distance from non-rigid stiffener (default=0, boundary >0, Unit:Length) 

	BOOL   bUseStifTop;           // PMS:LRFD12 BSC-20131224 AASHTO, LSD Flange Top에 대한
	int    nStiffenerTypeTop;     // 0 : Flat 1 : Tee
	int    nStifNumTop;           // Stiffener 개수(0=One stiffener, 1=Two stiffener) (default=0, boundary=0,1)
	double dPitchTop;             // Rigid striffener pitch (default=0, boundary >0, Unit:Length)
	double dSizeTop[4];           // 0: H 1:B 2:Tw 3:Tf
	double dFyTop;                // Fy

	BOOL   bUseStifBot;           // PMS:LRFD12 BSC-20131224 AASHTO, LSD Flange Bot에 대한
	int    nStiffenerTypeBot;     // 0 : Flat 1 : Tee
	int    nStifNumBot;           // Stiffener 개수(0=One stiffener, 1=Two stiffener) (default=0, boundary=0,1)
	double dPitchBot;             // Rigid striffener pitch (default=0, boundary >0, Unit:Length)
	double dSizeBot[4];           // 0: H 1:B 2:Tw 3:Tf
	double dFyBot;                // Fy

	BOOL   bUseStifWeb;           // PMS:LRFD12 BSC-20131224 AASHTO, LSD Web에 대한
	int    nStiffenerTypeWeb;     // 0 : Flat 1 : Tee
	int    nStifNumWeb;           // Stiffener 개수(0=One stiffener, 1=Two stiffener) (default=0, boundary=0,1)
	double dPitchWeb;             // Rigid striffener pitch (default=0, boundary >0, Unit:Length)
	double dSizeWeb[4];           // 0: H 1:B 2:Tw 3:Tf
	double dFyWeb;                // Fy

	void Initialize()
	{ 
		bUseStif = TRUE;
		bInterRigidStif=FALSE;   
		bInterNonRigidStif=FALSE;
		iStifNum = 0;           
		dht = 0.0;             
		dt = 0.0;              
		dPitch = 0.0;          
		dDistRstif = 0.0;      
		dDistNRstif = 0.0;     

		bUseStifTop = TRUE;       
		nStiffenerTypeTop = 0;    
		nStifNumTop = 0;          
		dPitchTop   = 0.0;    
		memset(dSizeTop, 0, sizeof(dSizeTop));
		dFyTop      = 0.0;   
		
		bUseStifBot = TRUE;       
		nStiffenerTypeBot = 0;    
		nStifNumBot = 0;          
		dPitchBot   = 0.0;    
		memset(dSizeBot, 0, sizeof(dSizeBot));
		dFyBot      = 0.0;   
		
		bUseStifWeb = TRUE;       
		nStiffenerTypeWeb = 0;    
		nStifNumWeb = 0;          
		dPitchWeb   = 0.0;    
		memset(dSizeWeb, 0, sizeof(dSizeWeb));
		dFyWeb      = 0.0;   
	}
	void Convert830(const T_CGTS_STIF_830& rData)
	{
		Initialize();
		bUseStif           = rData.bUseStif;					
		bInterRigidStif    = rData.bInterRigidStif;   
		bInterNonRigidStif = rData.bInterNonRigidStif;
		iStifNum          = rData.iStifNum;          
		dht               = rData.dht;               
		dt                = rData.dt;                
		dPitch            = rData.dPitch;            
		dDistRstif        = rData.dDistRstif;        
		dDistNRstif       = rData.dDistNRstif;       
	}
};

struct T_CGTS_D_830
{
	BOOL        bBothIJ;  // TRUE=Transverse stiffener를 I, J를 같게 입력할 경우 (default=FALSE)
	T_CGTS_STIF_830 Tstif[2]; // Transverse stiffener(I, J)  
};

struct T_CGTS_D
{
	BOOL        bBothIJ;  // TRUE=Transverse stiffener를 I, J를 같게 입력할 경우 (default=FALSE)
	T_CGTS_STIF Tstif[2]; // Transverse stiffener(I, J)  

	T_CGTS_D() {}
	T_CGTS_D(const T_CGTS_D& rData) { *this = rData; }
	T_CGTS_D& operator=(const T_CGTS_D& rData)
	{
		bBothIJ = rData.bBothIJ;
		Tstif[0] = rData.Tstif[0];
		Tstif[1] = rData.Tstif[1];
		return *this;
	}
	void Initialize()
	{
		bBothIJ = TRUE;
		Tstif[0].Initialize();
		Tstif[1].Initialize();
	}
	void Convert830(const T_CGTS_D_830& rData)
	{
		Initialize();
		bBothIJ    = rData.bBothIJ;
		Tstif[0].Convert830(rData.Tstif[0]);
		Tstif[1].Convert830(rData.Tstif[1]);
	}
};
