#define T_SCGD_K unsigned int
struct T_SCGD_D
{  
	// Shear Connector Place Info.
	int nNum; // Shear Connector Num
	double dfu; // Yield Resistance (Ry)
	double dDia; // Diameter (d)
	double dhsc; // Overall Height (hsc)
	double dSpace;

	// Shear Connector Place Group Data
	T_SCGD_K ScgdKey;
	CString strShearConnGroupName;
	T_ELEM_K StartElemKey;
	T_ELEM_K EndElemKey;
	int nStartElemIJ; // 0 : I , 1 : J
	int nEndElemIJ; // 0 : I , 1 : J
	double dLength; // Shear Connector Placing Length

	CArray<T_ELEM_K, T_ELEM_K> arGroupElemKey;

	T_SCGD_D() {}
	T_SCGD_D(const T_SCGD_D& rData) { *this = rData; }
	T_SCGD_D& operator=(const T_SCGD_D& rData)
	{
		nNum = rData.nNum;
		dfu = rData.dfu;
		dDia = rData.dDia;
		dhsc = rData.dhsc;
		dSpace = rData.dSpace;

		// Shear Connector Place Group Data
		ScgdKey = rData.ScgdKey;
		strShearConnGroupName = rData.strShearConnGroupName;
		StartElemKey = rData.StartElemKey;
		EndElemKey = rData.EndElemKey;
		nStartElemIJ = rData.nStartElemIJ;
		nEndElemIJ = rData.nEndElemIJ;
		dLength = rData.dLength;
		arGroupElemKey.Copy(rData.arGroupElemKey);

		return *this;
	}
	void Initialize()
	{
		nNum = 0;
		dfu = 0.0;
		dDia = 0.0;
		dhsc = 0.0;
		dSpace = 0.0;

		// Shear Connector Place Group Data
		ScgdKey =0;
		strShearConnGroupName = _T("");
		StartElemKey = 0;
		EndElemKey = 0;
		nStartElemIJ = 0;
		nEndElemIJ = 1;
		dLength = 0.0;
		arGroupElemKey.RemoveAll();
	}
};

