	double dGamma_C;    // Concrete, (default=1.0, boundary >0, Unit:None)
	double dGamma_S;    // Reinforcing steel, (default=1.0, boundary >0, Unit:None)
	double dGamma_M0;   // Structural steel, (default=1.0, boundary >0, Unit:None)
