	double dGamma_V;    // Shear resistance of a headed stud, (default=1.0, boundary >0, Unit:None)
	double dGamma_Ff;   // Equivalent constant amplitude stress range, (default=1.0, boundary >0, Unit:None)
	double dGamma_Mf;   // Fatigue strength, (default=1.0, boundary >0, Unit:None)
	double dGamma_Mfs;  // Fatigue strength of studs in shear, (default=1.0, boundary >0, Unit:None)
	double dt_Ld;       // Design life of the bridge in years. Resistance to Fatigue 사용(default=100.0, boundary >0, Unit:None)
	
	double dGamma_M_ser;
	double dk1;
	double dk2;
