// Composite Girder Longitudinal Stiffener.
#define T_CLRS_K T_SECT_K

// Compostie Girder Longitudinal Stiffener.
struct T_CLRS_STIF
{
	int     iBarNum;    // 배치 갯수 (default :0, boundary >0 )
	int     iStaZRef;   // Z의 배치 기준(0=Top, 1=Bottom : 단면 MBR의 Top, Bottom)
	double  dStaZ;      // 배치 위치(Z) // 양수, 상대 거리(iStaZRef) (default :0, boundary >0 )
	double  dPitch;     // 간격 (default :0, boundary >0 )
	double  dWidth;     // (default :0, boundary >0 ) Unit:Length
	double  dt;         // (default :0, boundary >0 ) Unit:Length
	void Initialize()
	{
		iBarNum     = 0;
		iStaZRef    = 0;
		dStaZ       = 0.0;
		dPitch      = 0.0;
		dWidth      = 0.0;
		dt          = 0.0;
	}
	BOOL IsSame(T_CLRS_STIF& rData)
	{
		if(iBarNum != rData.iBarNum ) return FALSE;
		if(iStaZRef!= rData.iStaZRef) return FALSE;
		if(dStaZ   != rData.dStaZ   ) return FALSE;
		if(dPitch  != rData.dPitch  ) return FALSE;
		if(dWidth  != rData.dWidth  ) return FALSE;
		if(dt      != rData.dt      ) return FALSE;

		return TRUE;
	}

};
struct T_CLRS_D 
{
	BOOL bLStifJ; // TRUE=Longitudinal siffener를 I, J 각각 입력할 경우 (default=FALSE)
	CArray<T_CLRS_STIF, T_CLRS_STIF&> LStif[2]; // Longitudinal siffener(I, J)  

	T_CLRS_D() {}
	T_CLRS_D(const T_CLRS_D& rData) { *this = rData; }
	T_CLRS_D& operator=(const T_CLRS_D& rData)
	{
		bLStifJ = rData.bLStifJ;
		LStif[0].Copy(rData.LStif[0]);
		LStif[1].Copy(rData.LStif[1]);
		return *this;
	}
	void Initialize()
	{
		bLStifJ = FALSE;
		LStif[0].RemoveAll();
		LStif[1].RemoveAll();
	}
};

struct T_CLRS_UDRD_D
{
	T_CLRS_K key;
	T_CLRS_D data;
};
struct T_CLRS_UDRD_D_RW
{
	T_CLRS_K key;
	BOOL bLStifJ;
	int  nLStifCount[2];
	void GetClrs(T_CLRS_K &rKey, T_CLRS_D &rData)
	{
		rKey = key;
		rData.bLStifJ = bLStifJ;
	}
	void SetClrs(const T_CLRS_K &rKey, const T_CLRS_D& rData)
	{
		key = rKey;
		bLStifJ = rData.bLStifJ;
		nLStifCount[0] = (int)rData.LStif[0].GetSize();
		nLStifCount[1] = (int)rData.LStif[1].GetSize();
	}  
};
struct T_CLRS_UNIT
{
	T_CLRS_UNIT()
	{
		dStaZ  = D_UNITSYS_BASE_LENGTH;
		dPitch = D_UNITSYS_BASE_LENGTH;
		dWidth = D_UNITSYS_BASE_LENGTH;
		dt     = D_UNITSYS_BASE_LENGTH;
	}
	int dStaZ;
	int dPitch;
	int dWidth;
	int dt;
};
