	BOOL     bActiveOnly; // Avg.Nodal선택시 활성화된 Nodal에 대해서만 평균할지 여부
	int      iDir       ; // 설계 방향(0=X-Dir, 1=Y-Dir)
	int      iRhoStand  ; // 최소철근비 산출기준(0=보 , 1=슬래브) default=1
	int      iServCond  ; // 사용성 검토조건 (0=건조환경1, 1=건조환경2, 2=습윤환경1, 3=습윤환경2, 4=부식성환경, 5= 고부식성환경 ) default=0
	BOOL     bStirrup	  ; // 허용균열폭 산정시 전단철근 포함.
	double   dDt	      ; // Design하기 위한 철근 도심의 임의 위치 .(Top에서)
	double   dDb        ; // Design하기 위한 철근 도심의 임의 위치 .(Bot에서)
	CString  strRemark  ; // 비고
	int      nPlateMemb ; // 0:Beam 1:Wall v811추가

	void Initialize()
	{
		strName     = _T("");
		arElemK.RemoveAll();
		iAxisType		= 0;
		ucsKey			= 0;
		bPrintUCS   = FALSE;		
		iAnaType    = 0;
		bActiveOnly = FALSE;
		iDir				= 0;
		iRhoStand   = 1;
		iServCond   = 0;    
		bStirrup    = FALSE; 
		dDt         = 0.0;
		dDb         = 0.0;
		strRemark = _T("");   // 비고
		nPlateMemb = 0;
	}
