		iAnaType = rData.iAnaType;
		bActiveOnly = rData.bActiveOnly;
		iDir = rData.iDir;
		iRhoStand = rData.iRhoStand;
		iServCond = rData.iServCond;
		bStirrup = rData.bStirrup;
		dDt = rData.dDt;
