// Design Parameter for RC Wall
#define T_RCWA_K T_ELEM_K
struct T_RCWA_D	
{	
	int    iSlenderType	 ; // 장.단주중 설계방법 ( 0:단주검토,  1:장단주검토) - 모멘트확대계수(Moment Magnification factor) 적용여부
	BOOL   bAutoBoundary ; // 횡구속여부 자동 결정 (default = FALSE)		
	int    iXDirBd       ; // X-Direction 횡구속여부(0=Unbraced|Sway, 1=Braced | Non-sway) default=1			
	BOOL   bAutoEqCoeff  ; // 등가모멘트 보정계수 자동계산 (default=FALSE)	
	BOOL   bAutoDeltans  ; // Delta_ns 자동계산(default=FALSE)	
	BOOL   bAutoDeltas   ; // Delta_s 자동계산(default=FALSE)		
	double dCm           ; // 등가모멘트 보정계수, 강축(default = 1) (Check: dCm>0)		
	double dDelta_ns     ; // (Check : dDelta_ns >=1.0)	
	double dDelta_s      ; // (Check : dDelta_s >=1.0)		
	int    iHaunchType   ; // 헌치의 위치(0:양면, 1:전면, 2:배면) (v730에서는 사용자에게 보여주지 않으며, 내부적으로 양면만 제공함 SHIN, 2007.05.17)
	double dHaunch_hi	   ; // I단의 헌치높이
	double dHaunch_hj	   ; // J단의 헌치높이
	double dDt	         ; // Design하기 위한 철근 도심의 임의 위치 .(Top(전면)에서)	
	double dDb	         ; // esign하기 위한 철근 도심의 임의 위치 .(Bot(배면)에서)	
	BOOL   bRhomax	     ; // 최대철근비를 검토할지 여부	
	double dRhomax	     ; // 최대철근비. (default = 0.08)       (Check: dRhomax>0)	
	int    iServCond     ; // 사용성 검토조건 (0=건조환경1, 1=건조환경2, 2=습윤환경1, 3=습윤환경2, 4=부식성환경, 5= 고부식성환경 ) default=0
	BOOL   bStirrup	     ; // 허용균열폭 산정시 전단철근 포함.
	BOOL   bPosi[3]	     ; // 0=I단, 1=J단, 2=Mid
	BOOL   bUserBd_NS    ; // 횡구속 Beta_d 입력 (default=FALSE) 
	BOOL   bUserBd_S     ; // 비횡구속 Beta_d 입력 (default=FALSE) 
	double dBd_nsy       ; // y-횡구속 Bd (default=0.6) , (Boundary : dBd_nsy>=0) 
	double dBd_sy        ; // y-비횡구속 Bd (default=0.6) , (Boundary : dBd_sy>=0)
	CString strRemark		 ;
	BOOL   bAutoRebarPosi; // 필요철근량 산출시 작용하중에 따라 주철근량의 전면과 배면의 비율을 자동 조정여부(TURE:최적비율적용, FALSE:사용자비율bAutoRebarPosi적용) (default : TRUE)
	double dTopRebarRatio; // 필요철근량 산출시 전체 주철근량중 전면철근의 비율(bAutoRebarPosi=FALSE시 사용) (default : 0.5,  Boundary : 0.0<=dTopRebarRatio<=1.0)
	
	void Initialize()
	{
		iSlenderType  = 1; 
		bAutoBoundary = FALSE; 
		iXDirBd       = 1; 
		bAutoEqCoeff  = FALSE; 
		bAutoDeltans  = FALSE; 
		bAutoDeltas   = FALSE; 
		dCm           = 1.0; 
		dDelta_ns     = 1.0; 
		dDelta_s      = 1.0; 
		iHaunchType   = 0;
		dHaunch_hi    = 0.0; 
		dHaunch_hj    = 0.0; 
		dDt           = 0.0; 
		dDb           = 0.0; 
		bRhomax       = FALSE; 
		dRhomax       = 0.08; 
		iServCond     = 1; 
		bStirrup      = FALSE; 
		for(int i=0;i<3;i++)
			bPosi[i]    =0;
		bUserBd_NS    = FALSE;
		bUserBd_S     = FALSE;
		dBd_nsy       = 0.6;
		dBd_sy        = 0.6;
		strRemark     = _T("");
		bAutoRebarPosi= TRUE;
		dTopRebarRatio= 0.5;
	}
};
