	double  dDb[3][5];          // Bottom에서 거리 (3:I,M,J, 5:Layer)
	double  dTopBarNum[3][5];   // Top 철근 개수 (bUnitWidth == TRUE:단위폭당 개수    bUnitWidth == FALSE:전체 개수)
	double  dBotBarNum[3][5];   // Bottom 철근 개수 (bUnitWidth == TRUE:단위폭당 개수    bUnitWidth == FALSE:전체 개수)
