struct _RCSC_CRES_LCOMRC
{
	_RCSC_CRES_POSIRC PosData[CONST_RCSC_iPOS_DIV];
	void Initialize()
	{
		for(int i=0; i<CONST_RCSC_iPOS_DIV; i++)	PosData[i].Initialize();
	}
	_RCSC_CRES_LCOMRC()	{}
	_RCSC_CRES_LCOMRC(_RCSC_CRES_LCOMRC& rData)	{*this = rData;}
	_RCSC_CRES_LCOMRC& operator = (_RCSC_CRES_LCOMRC& rData)
	{
		for(int i=0; i<CONST_RCSC_iPOS_DIV; i++)
			PosData[i] = rData.PosData[i];
		return *this;
	}

};

struct _RCSC_CRES_ELEMRC
{	
	BOOL bCheck;
	int iElemNo;
	int iSectNo, iMatlNo;
	double dHeight;
	double dLy, dLz;
	double dKy, dKz;
	BOOL bBracedY, bBracedZ;
	double dUserCtcUpFactor;
	CMap<int,int&,_RCSC_CRES_LCOMRC,_RCSC_CRES_LCOMRC&>	arLcomData;
	void Initialize()
	{
		bCheck=FALSE;
		iElemNo=0;
		iSectNo=0; iMatlNo=0;
		dHeight=0.0;
		dLy=0.0; dLz=0.0;
		dKy=0.0; dKz=0.0;
		bBracedY=FALSE; bBracedZ=FALSE;
		dUserCtcUpFactor=0.0;
		arLcomData.RemoveAll();
	}
	_RCSC_CRES_ELEMRC()	{}
	_RCSC_CRES_ELEMRC(_RCSC_CRES_ELEMRC& rData)	{*this = rData;}
	_RCSC_CRES_ELEMRC& operator = (_RCSC_CRES_ELEMRC& rData)
	{
		Initialize();
		bCheck   = rData.bCheck;
		iElemNo  = rData.iElemNo;
		iSectNo  = rData.iSectNo;
		iMatlNo  = rData.iMatlNo;
		dHeight  = rData.dHeight;
		dLy			 = rData.dLy;
		dLz			 = rData.dLz;
		dKy			 = rData.dKy;
		dKz			 = rData.dKz;
		bBracedY = rData.bBracedY;
		bBracedZ = rData.bBracedZ;
		dUserCtcUpFactor = rData.dUserCtcUpFactor;
		_RCSC_CRES_LCOMRC rLcomData;
		int Index=0;
		POSITION Pos = rData.arLcomData.GetStartPosition();
		while(Pos)
		{
			rLcomData.Initialize();
			rData.arLcomData.GetNextAssoc(Pos, Index, rLcomData);
			arLcomData.SetAt(Index, rLcomData);
		}
		return *this;
	}
};

struct _RCSC_CRES_ELEMRC_UNIT
{	
	_RCSC_CRES_ELEMRC_UNIT()
	{
	  dHeight = D_UNITSYS_BASE_LENGTH;
	  dLy = dLz = D_UNITSYS_BASE_LENGTH;	  
	}
	int dHeight;
	int dLy, dLz;
};

