	void ConvertToMap(_RCSC_CRES_ELEMRC& rData)
	{
		rData.bCheck   = bCheck;
		rData.iElemNo  = iElemNo;
		rData.iSectNo  = iSectNo;
		rData.iMatlNo  = iMatlNo;
		rData.dHeight  = dHeight;
		rData.dLy			 = dLy;
		rData.dLz			 = dLz;
		rData.dKy			 = dKy;
		rData.dKz			 = dKz;
		rData.bBracedY = bBracedY;
		rData.bBracedZ = bBracedZ;
		rData.dUserCtcUpFactor = dUserCtcUpFactor;
		//
		rData.arLcomData.RemoveAll();
		int nLcomKey = (int)arLcomKey.GetSize();
		if(nLcomKey>0)
		{
			rData.arLcomData.InitHashTable(nLcomKey);
			for(int i=0; i<nLcomKey; i++)
			{
				int iLcomK = arLcomKey[i];
				_RCSC_CRES_LCOMRC LcomData = arLcomD[i];
				rData.arLcomData.SetAt(iLcomK, LcomData);
			}
		}
	}
