struct _RCSC_CRES_ELEMRC_CH_RW
{
	BOOL bCheck;
	int iElemNo;
	int iSectNo, iMatlNo;
	double dHeight;
	double dLy, dLz;
	double dKy, dKz;
	BOOL bBracedY, bBracedZ;
	double dUserCtcUpFactor;
	UINT nLcomKey;
	UINT nLcomData;
	void Initialize()
	{
		bCheck=FALSE;
		iElemNo=0;
		iSectNo=0; iMatlNo=0;
		dHeight=0.0;
		dLy=0.0; dLz=0.0;
		dKy=0.0; dKz=0.0;
		bBracedY=FALSE; bBracedZ=FALSE;
		dUserCtcUpFactor=0.0;
		nLcomKey=0;
		nLcomData=0;
	}

	void GetCresElem(_RCSC_CRES_ELEMRC_CH& rData)
	{
		rData.bCheck   = bCheck;
		rData.iElemNo  = iElemNo;
		rData.iSectNo  = iSectNo;
		rData.iMatlNo  = iMatlNo;
		rData.dHeight  = dHeight;
		rData.dLy			 = dLy;
		rData.dLz			 = dLz;
		rData.dKy			 = dKy;
		rData.dKz			 = dKz;
		rData.bBracedY = bBracedY;
		rData.bBracedZ = bBracedZ;
		rData.dUserCtcUpFactor = dUserCtcUpFactor;    
	}
	void SetCresElem(const _RCSC_CRES_ELEMRC& rData)
	{
		bCheck   = rData.bCheck;
		iElemNo  = rData.iElemNo;
		iSectNo  = rData.iSectNo;
		iMatlNo  = rData.iMatlNo;
		dHeight  = rData.dHeight;
		dLy			 = rData.dLy;
		dLz			 = rData.dLz;
		dKy			 = rData.dKy;
		dKz			 = rData.dKz;
		bBracedY = rData.bBracedY;
		bBracedZ = rData.bBracedZ;
		dUserCtcUpFactor = rData.dUserCtcUpFactor;
		nLcomKey = (int)rData.arLcomData.GetCount();
		nLcomData = (int)rData.arLcomData.GetCount();
	}

};

