	double dVuy[COLM_SHOW], dVuz[COLM_SHOW];
	double dVsyReqD[COLM_SHOW], dVszReqD[COLM_SHOW], dpVcyD[COLM_SHOW], dpVczD[COLM_SHOW], dpVsyD[COLM_SHOW], dpVszD[COLM_SHOW]; // Dgn.
	double dVsyReq[COLM_SHOW], dVszReq[COLM_SHOW], dpVcy[COLM_SHOW], dpVcz[COLM_SHOW], dpVsy[COLM_SHOW], dpVsz[COLM_SHOW];
	double dVu[COLM_SHOW], dpVn[COLM_SHOW];
