struct _RCSC_COL_XL_PMDATA
{
	D_RCSC_PM_UNIT Pm_emin[3];                                  // 최소편심상태의 단면 강도
	CMap<int, int, D_RCSC_PM_UNIT, D_RCSC_PM_UNIT> arPmUnit[3]; // I,M,J
	void Initialize()
	{
		for(int i=0; i<3; i++)
		{
			Pm_emin[i].Initialize();
			arPmUnit[i].RemoveAll();
		}
	}
	_RCSC_COL_XL_PMDATA()	{}
	_RCSC_COL_XL_PMDATA(_RCSC_COL_XL_PMDATA& rData)	{*this = rData;}
	_RCSC_COL_XL_PMDATA& operator = (_RCSC_COL_XL_PMDATA& rData)
	{
		Initialize();
		for(int i=0; i<3; i++)
		{
			Pm_emin[i] = rData.Pm_emin[i];

		  D_RCSC_PM_UNIT rPMdata;
		  int Index=0;
		  POSITION Pos = rData.arPmUnit[i].GetStartPosition();
		  while(Pos)
		  {
			  rPMdata.Initialize();
			  rData.arPmUnit[i].GetNextAssoc(Pos, Index, rPMdata);
			  arPmUnit[i].SetAt(Index, rPMdata);
		  }
		}
		return *this;
	}

};

