struct T_RCS_BRESULT_RPT//_RCS_BRESULT_DATA
{
	T_RCS_BBASE_RPT	BaseData;
	// Key Value is Position No.
	CMap<int, int&, T_RCS_BEAM_POS_RPT, T_RCS_BEAM_POS_RPT&>	PosiData;
	CMap<int, int&, T_RCS_BEAM_SER_RPT, T_RCS_BEAM_SER_RPT&>	ServData;
	void Initialize()
	{
		BaseData.Initialize();
		PosiData.RemoveAll();
		ServData.RemoveAll();
	}
	T_RCS_BRESULT_RPT()	{}
	T_RCS_BRESULT_RPT(const T_RCS_BRESULT_RPT& rData)	{*this = rData;}
	T_RCS_BRESULT_RPT& operator = (const T_RCS_BRESULT_RPT& rData)
	{
		BaseData = rData.BaseData;
		T_RCS_BEAM_POS_RPT rPosData;
		int IndexP=0;
		POSITION PosP = rData.PosiData.GetStartPosition();
		while(PosP)
		{
			rPosData.Initialize();
			rData.PosiData.GetNextAssoc(PosP, IndexP, rPosData);
			PosiData.SetAt(IndexP, rPosData);
		}
		T_RCS_BEAM_SER_RPT rSerData;
		int IndexS=0;
		POSITION PosS = rData.ServData.GetStartPosition();
		while(PosS)
		{
			rSerData.Initialize();
			rData.ServData.GetNextAssoc(PosS, IndexS, rSerData);
			ServData.SetAt(IndexS, rSerData);
		}
		return *this;
	}
};

struct T_RCS_BRESULT_RPT_DATA
{
	int iDgnType;  
	CArray<UINT,UINT> arElemKey; // Element
	CArray<UINT,UINT> arSectKey; // Section
	CArray<T_RCS_BRESULT_RPT,T_RCS_BRESULT_RPT> arElemData;
	CArray<T_RCS_BRESULT_RPT,T_RCS_BRESULT_RPT> arSectData;

	void Initialize()
	{
		iDgnType=0;
		arElemKey.RemoveAll();
		arSectKey.RemoveAll();
		arElemData.RemoveAll();
		arSectData.RemoveAll();
	}
	T_RCS_BRESULT_RPT_DATA()	{}
	T_RCS_BRESULT_RPT_DATA(T_RCS_BRESULT_RPT_DATA& rData)	{*this = rData;}
	T_RCS_BRESULT_RPT_DATA& operator = (T_RCS_BRESULT_RPT_DATA& rData)
	{
		iDgnType = rData.iDgnType;
		arElemKey.Copy(rData.arElemKey);
		arSectKey.Copy(rData.arSectKey);
		arElemData.Copy(rData.arElemData);
		arSectData.Copy(rData.arSectData);
		return *this;
	}
};

