struct T_RCS_COLM_LCB_RPT//_RCS_COLM_LCB_DATA	// by Load Combination.
{
	// Common Data.
	CString res_sPosiNa;
	double res_dPu, res_dVu;
	double res_dRatV;
	CString res_sMainbarNa;
	CString res_sCornerbarNa;
	CString res_sSubbarNa; // Coded by Seungjun MNet:No.2484 ('20061129) 
	double res_dRealRota;	// Modified Rota.
	double res_ddT;
	// Only Checking Data.
	CString res_CHK;
	double res_dpPnmax;
	double res_dMFy, res_dMFz;	// Moment Magnification Factor.
	double res_dMcy, res_dMcz;	// Factored Moment.
	double res_dRatNc[4];				// 0=NonEQ, 1=EQ, 2=1.2(D+0.5L).
	double res_dRatMy, res_dRatMz, res_dRatP;
	// Only Design Data.
	double res_dMu;		// sqrt(Muy^2 + Muz^2).
	double res_dRatM;	// Mu/phiMn.
	double res_dAsV, res_dAsH;
	int res_iMainbarNum, res_iMainbarArr;	// 개수, 가로줄수
	double res_dSubbarDist;
	int res_iSubbarNum[2];	// 0=y, 1=z.
	// Adhesive Stress.
	double res_dAdhtay, res_dAdhfay;
	double res_dAdhtaz, res_dAdhfaz;
	// add by SeungJun (`06.05.04)
	// design strength of moment by Pu on PM curve for strong-comumn weak-beam design for USD.
	double res_dPuMn[2];   // I,J
	double res_dPuMny[2];  // I,J
	double res_dPuMnz[2];  // I,J
	// add by SeungJun (`06.05.19)
	// NO.2077 GB 철근콘크리트 구조층 실제 전단재하능력 평가
	double res_dVcyy[2];  // I,J
	double res_dVcyz[2];  // I,J
	double res_dMcyy[2];  // I,J
	double res_dMcyz[2];  // I,J
	// Coded by Seungjun ('20070308) MNet:No.2669.
	double res_dVey[2]; // 0:CW, 1:CCW.
	double res_dVez[2]; // 0:CW, 1:CCW.
	// Coded by SeungJun MNET:3433  '20080523
	BOOL   res_bShearEQ[2]; // Local-z, y.

	void Initialize()
	{
		// Common Data.
		res_sPosiNa=_T("");
		res_dPu=0.0; res_dVu=0.0;
		res_dRatV=0.0;
		res_sMainbarNa=_T(""); 
		res_sCornerbarNa=_T(""); 
		res_sSubbarNa=_T(""); // Coded by Seungjun MNet:No.2484 ('20061129)
		res_dRealRota=0.0;
		res_ddT=0.0;
		// Only Checking Data.
		res_CHK=_T("");
		res_dpPnmax=0.0;
		res_dMFy=0.0; res_dMFz=0.0;
		res_dMcy=0.0; res_dMcz=0.0;
		for(int i=0; i<4; i++)	res_dRatNc[i]=0.0;
		res_dRatMy=0.0; res_dRatMz=0.0; res_dRatP=0.0;
		// Only Design Data.
		res_dMu=0.0;
		res_dRatM=0.0;
		res_dAsV=0.0; res_dAsH=0.0;
		res_iMainbarNum=0; res_iMainbarArr=0;
		res_dSubbarDist=0.0;
		res_iSubbarNum[0]=0;
		res_iSubbarNum[1]=0;
		res_dAdhtay=0.0; res_dAdhfay=0.0;
		res_dAdhtaz=0.0; res_dAdhfaz=0.0;
		for(int j=0; j<2; j++)
		{ res_dPuMn[j]=0.0; res_dPuMny[j]=0.0; res_dPuMnz[j]=0.0;
			res_dVcyy[j] =0.0; res_dVcyz[j]  =0.0; 
			res_dMcyy[j] =0.0; res_dMcyz[j]  =0.0; 
			// Coded by Seungjun ('20070308) MNet:No.2669.
			res_dVey[j] = 0.0;  res_dVez[j] = 0.0;
		}
		res_bShearEQ[0]= TRUE;
		res_bShearEQ[1]= TRUE;
	}
};

