struct T_RCS_CRESULT_RPT//_RCS_CRESULT_DATA
{
	T_RCS_CBASE_RPT BaseData;
	// Key Value is Load Combination No.
	CMap<int, int&, T_RCS_COLM_LCB_RPT, T_RCS_COLM_LCB_RPT&> LcomData;
	T_RCS_COLM_LCB_RPT UniAxisD; // BaseData.res_iLcomNo 로 Map에서 찾은 Data
	CString strBar;
	CString strRatP;
	CString strRatM; // m_pMyDB->IsUniOnlyM() 일경우 출력 
	CString strRatMy;
	CString strRatMz;
	CString strRatV;
	void Initialize()
	{
		BaseData.Initialize();
		LcomData.RemoveAll();
		UniAxisD.Initialize();
		strBar=_T("");
		strRatP=_T("");
		strRatM=_T("");
		strRatMy=_T("");
		strRatMz=_T("");
		strRatV=_T("");
	}
	T_RCS_CRESULT_RPT()	{}
	T_RCS_CRESULT_RPT(const T_RCS_CRESULT_RPT& rData)	{*this = rData;}
	T_RCS_CRESULT_RPT& operator = (const T_RCS_CRESULT_RPT& rData)
	{
		BaseData = rData.BaseData;
		T_RCS_COLM_LCB_RPT rLcbData;
		int Index=0;
		POSITION Pos = rData.LcomData.GetStartPosition();
		while(Pos)
		{
			rLcbData.Initialize();
			rData.LcomData.GetNextAssoc(Pos, Index, rLcbData);
			LcomData.SetAt(Index, rLcbData);
		}
		UniAxisD = rData.UniAxisD;
		strBar = rData.strBar;
		strRatP = rData.strRatP;
		strRatM = rData.strRatM;
		strRatMy = rData.strRatMy;
		strRatMz = rData.strRatMz;
		strRatV = rData.strRatV;
		return *this;
	}
};

