{
	T_RSDM_KEY keymap;
	struct
	{
		unsigned int OType :  4; // Object Type, 0-16         // 1:Element  2:Elastic Link  3:General Link
		unsigned int OKey  : 28; // Key,         0-268435456
	}key;
};
struct T_RSDM_D
{
	int    nMemberType;            // MemberType(1:Abutment  2:Foundation  4:판식고무지지점  5:활동쟁반형지지점  6:고정쟁반형지지점  7:Main arch)
	int    nPierType;              // 교각 - 교각형식(0:정형교량  1:비정형교량) (nMemberType == 0 일때에만 사용)                                   <- 사용하지 않음(09.11.06)
	double dFdnAllowGround;        // 기초 - 지반재하력 허용값 (nMemberType == 2 일때에만 사용, value > 0)
	double dCappingBeamSpan;       // Capping Beam - 계산스팬 (nMemberType == 3 일때에만 사용, value > 0)                                          <- 사용하지 않음(09.11.06)
	double dSupportRubberThick;    // 판식고무지지점 - 고무층두께 (nMemberType == 4 일때에만 사용, value > 0)
	double dSupportFrictionFactor; // 판식고무지지점 - 지지점동적마찰계수 (nMemberType == 4 일때에만 사용, value > 0)
	double dSupportAllowHorizonDis;// 활동쟁반형지지점 - 허용미끌림수평변위 (nMemberType == 5 일때에만 사용, value > 0)
	double dSupportMaxHorizonLoad; // 고정쟁반형지지점 - 최대수평재하력 (nMemberType == 6 일때에만 사용, value > 0)
	int    nOutputType;            //  (nMemberType == 1,2,7 일때 0:None 1:I 2:J 3:I&J,  nMemberType == 4,5,6 일때 0:None 1:출력)
	void Initialize()
	{
		nMemberType = 0;
		nPierType   = 0;
		dFdnAllowGround        = 0.0;
		dCappingBeamSpan       = 0.0;
		dSupportRubberThick    = 0.0;
		dSupportFrictionFactor = 0.0;
		dSupportAllowHorizonDis= 0.0;
		dSupportMaxHorizonLoad = 0.0;
		nOutputType = 0;
	}
	
};
