	double dPierYieldCurvature[2];   // Pier - 사용자 입력 항복곡률
	double dPierUltimateCurvature[2];// Pier - 사용자 입력 극한곡률
	double dCappingBeamSpan;       // Capping Beam - 계산스팬 (nMemberType == 3 일때에만 사용, value > 0)
	int    nOutputType;            // (nMemberType == 0,3일때 0:None 1:I 2:J 3:I&J)
	
	BOOL   bPierUserMPhi;
	double dPierUser_M[3];   //(value >= 0)
	double dPierUser_Phi[3]; //(value >= 0)
	void Initialize()
	{
		nMemberType   = 0;
		aElemList.RemoveAll();		
		aNodeList.RemoveAll();
		nPierPHingeRegionType = 0;
		dPierHn          = 0.0;
		bPierDColumnBent = FALSE;
		dPierAllowDisp   = 0.0;
		PierMpccKey      = 0;
		for(int i=0 ; i<2 ; i++)
		{
			arPierUserMPhi[i].RemoveAll();
			dPierYieldCurvature[i] = 0.0;
			dPierUltimateCurvature[i] = 0.0;
		}
		dCappingBeamSpan = 0.0;
		nOutputType = 0;
		
		bPierUserMPhi = FALSE;
		dPierUser_M[0]   = dPierUser_M[1]   = dPierUser_M[2]   = 0.0;
		dPierUser_Phi[0] = dPierUser_Phi[1] = dPierUser_Phi[2] = 0.0;
	}	
