#define T_RLCC_K unsigned int
struct T_RLCC_D
{
	int nType;            // 계산대상(0:RC단주교각)
	CString strName;      // 이름
	CArray<T_ELEM_K, T_ELEM_K> aElemList; //검토할 부재를 구성하는 Element List	
	BOOL bTraverse;       //교축방향 설계여부
	BOOL bLongitude;      //교축직각방향 설계여부
	double dWu;           // 등가중량 : 상부구조의 중량
	double dWp;           // 등가중량 : 교각구체의 중량
	double dNaturalFrequency[2]; //고유주기
	double dActHeight;    // 하단에서 관성력 작용위치까지 거리
	double dInitMoment[2];// 사하중에 의한 편심모멘트
	double dInitAxisForce;// 사하중에 의한 반력

	void Initialize()
	{
		nType = 0;
		strName = _T("");
		aElemList.RemoveAll();
		bTraverse  = TRUE;
		bLongitude = FALSE;
		dWu = 0.0;
		dWp = 0.0;
		dNaturalFrequency[0] = 0.0;
		dNaturalFrequency[1] = 0.0;
		dActHeight = 0.0;
		dInitMoment[0] = 0.0;
		dInitMoment[1] = 0.0;
		dInitAxisForce = 0.0;
	}
	T_RLCC_D()	{}
	T_RLCC_D(T_RLCC_D& rData)	{*this = rData;}
	T_RLCC_D& operator = (T_RLCC_D& rData)
	{
		nType                = rData.nType               ;
		strName              = rData.strName             ;
		aElemList.Copy(rData.aElemList);
		bTraverse            = rData.bTraverse           ;
		bLongitude           = rData.bLongitude          ;
		dWu                  = rData.dWu                 ;
		dWp                  = rData.dWp                 ;
		dNaturalFrequency[0] = rData.dNaturalFrequency[0];
		dNaturalFrequency[1] = rData.dNaturalFrequency[1];
		dActHeight           = rData.dActHeight          ;
		dInitMoment[0]       = rData.dInitMoment[0]      ;
		dInitMoment[1]       = rData.dInitMoment[1]      ;
		dInitAxisForce       = rData.dInitAxisForce      ;
		return *this;
	}
};
