struct T_SLAB_BAR
{
    double dSpace;
    double dCover; // for engine
    CString strSize; // ex) P12 or P12+P16
    CString strInfo; // ex) "P12@200" or "No good Rebar Size(s) and Spacing(s)"

    void Initialize()
    {
        dSpace = 0.0;
        dCover = 0.0;
        strSize.Empty();
        strInfo.Empty();
    }

    T_SLAB_BAR() { Initialize(); }
    T_SLAB_BAR(const T_SLAB_BAR& src) { *this = src; }
    T_SLAB_BAR& operator= (const T_SLAB_BAR& src)
    {
        dSpace  = src.dSpace;
        dCover  = src.dCover;
        strSize = src.strSize;
        strInfo = src.strInfo;
        return *this;
    }
};

const int iConstMaxNo	= 4;	// 4 Node.
struct T_SLAB_POS
{
	int iLCBNo;
	double dN;
	double dMu;
    double dpMn;
	double dAsReq;
    double dAsUse;
	double dRhoReq;
    double dRhoUse;
    double dRhoCom;
	double dRatM;
    T_SLAB_BAR Rebar;
    T_SLAB_BAR AddRebar;
    // PMS:HSSHIM-20121104 Eurocode2:04의 NTC2012 기준추가시 중립축비(x/d) 검토 항목추가
    double dRatXd; // (x/d)
    double dLimXd; // (x/d)limit
    int nCriticalReferKey;

	void Initialize()
	{
		iLCBNo = 0;
        dN     = 0;
        dMu    = 0.0;
        dpMn   = 0.0;
        dAsReq = 0.0;
        dAsUse = 0.0;
        dRhoReq = 0.0;
        dRhoUse = 0.0;
        dRhoCom = 0.0;
		dRatM   = 0.0;
        Rebar.Initialize();
        AddRebar.Initialize();
		dRatXd = 0.0;
        dLimXd = 0.0;
        nCriticalReferKey = 0;
	}
	T_SLAB_POS() {}
	T_SLAB_POS(const T_SLAB_POS& sData)
    {
        *this = sData;
    }
	T_SLAB_POS& operator = (const T_SLAB_POS& sData)
	{
		iLCBNo	= sData.iLCBNo;
		dN      = sData.dN;
		dMu		= sData.dMu;
		dpMn	= sData.dpMn;
		dAsReq	= sData.dAsReq;
		dAsUse	= sData.dAsUse;
        dRhoReq	= sData.dRhoReq;
        dRhoUse	= sData.dRhoUse;
        dRhoCom = sData.dRhoCom;
        dRatM	= sData.dRatM;
        Rebar    = sData.Rebar;
        AddRebar = sData.AddRebar;
        dRatXd   = sData.dRatXd;
        dLimXd   = sData.dLimXd;
        nCriticalReferKey = sData.nCriticalReferKey;

		return *this;
	}

    double GetXDRatioToLimit() const
    {
        return fabs(dLimXd) < 1.0e-7 ? 99.99 : ( dRatXd / dLimXd );
    }
};

struct T_RSL2_D // 2way slab flexural design result.
{
	int iNodeNum;
	double dB, dT; // Bottom cover, Top Cover
	T_SLAB_POS Bot[iConstMaxNo];
	T_SLAB_POS Top[iConstMaxNo];

	void Initialize()
	{
		iNodeNum = 0;
		dB = 0.0;
		dT = 0.0;
		for(int i=0; i<iConstMaxNo; i++)
		{
			Bot[i].Initialize();
			Top[i].Initialize();
		}
	}
	T_RSL2_D() {}
	T_RSL2_D(const T_RSL2_D& sData)	{*this = sData;}
	T_RSL2_D& operator = (const T_RSL2_D& sData)
	{
		iNodeNum  = sData.iNodeNum;
		dB        = sData.dB;
		dT        = sData.dT;
		for(int i=0; i<iConstMaxNo; i++)
		{
			Bot[i] = sData.Bot[i];
			Top[i] = sData.Top[i];
		}
		return *this;
	}  
};

