struct T_SSER_POS
{	
    T_SLAB_BAR Rebar;
    T_SLAB_BAR AddRebar;

	// Stress
	int iStrLCBNo;
	double dStrMu, dStrMuD, dStrMuL;
	double dStress[2];  // 0:concrete 1:Steel stress
	double dAStress[2]; // 0:k2*fck 1:k3*fyk - Allowable stess
	double dStrRat[2];

	// Crack
	int iCrkLCBNo;
	double  dCrkN;//For China Crack TextOut
	double  dCrkMu;
	double  dwk;  // 발생균열
	double  dAwk; // 허용균열
	double  dAsmin;
	double  dASpace;
	double  dARebarDia;
	double  dCrkRat[4];

	// Deflection
	int iDefLCBNo;
	double  dDefMu;
	double  dElasticDsp;
	double  dCrackedDsp;
	double  dCreepedDsp;
	double  dAllowDsp;
    int     nCriticalReferKeyDef;
	
	// AniCrack
	int		iACrkLCBNo;
	double  dAniCrack;

	void Initialize()
	{
        Rebar.Initialize();
        AddRebar.Initialize();

		iStrLCBNo  = 0;
		dStrMu     = 0.0;
		dStrMuD    = 0.0;
		dStrMuL    = 0.0;
        for ( int i = 0 ; i < 2 ; ++i )
        {
            dStress [i] = 0.0;
            dAStress[i] = 0.0;
            dStrRat [i] = 0.0;
        }		

		iCrkLCBNo  = 0;
		dCrkN	   = 0.0;
		dCrkMu     = 0.0;
		dwk        = 0.0;
		dAwk       = 0.0;
		dAsmin     = 0.0;
		dASpace    = 0.0;
		dARebarDia = 0.0;
        for ( int i = 0; i < 4 ; ++i )
        {
            dCrkRat[i] = 0.0;
        }

		iDefLCBNo  = 0;
		dDefMu     = 0.0;
		dElasticDsp= 0.0;
		dCrackedDsp= 0.0;
		dCreepedDsp= 0.0;
		dAllowDsp  = 0.0;
        nCriticalReferKeyDef = 0;

		iACrkLCBNo	= 0;
		dAniCrack	=- 0.0;
	}
	T_SSER_POS() {}
	T_SSER_POS(const T_SSER_POS& sData)	{*this = sData;}
	T_SSER_POS& operator = (const T_SSER_POS& sData)
	{
        Rebar    = sData.Rebar;
        AddRebar = sData.AddRebar;

		iStrLCBNo  = sData.iStrLCBNo;
		dStrMu     = sData.dStrMu;
		dStrMuD    = sData.dStrMuD;
		dStrMuL    = sData.dStrMuL;
        for ( int i = 0 ; i < 2 ; ++i )
        {
            dStress [i] = sData.dStress [i];
            dAStress[i] = sData.dAStress[i];
            dStrRat [i] = sData.dStrRat [i];
        }		

		iCrkLCBNo  = sData.iCrkLCBNo;
		dCrkN	   = sData.dCrkN;
		dCrkMu     = sData.dCrkMu;
		dwk        = sData.dwk;
		dAwk       = sData.dAwk;
		dAsmin     = sData.dAsmin;
		dASpace    = sData.dASpace;
		dARebarDia = sData.dARebarDia;
        for ( int i = 0; i < 4 ; ++i )
        {
            dCrkRat[i] = sData.dCrkRat[i];
        }

		iDefLCBNo  = sData.iDefLCBNo;
		dDefMu     = sData.dDefMu;
		dElasticDsp= sData.dElasticDsp;
		dCrackedDsp= sData.dCrackedDsp;
		dCreepedDsp= sData.dCreepedDsp;
		dAllowDsp  = sData.dAllowDsp;
        nCriticalReferKeyDef = sData.nCriticalReferKeyDef;

		iACrkLCBNo	= sData.iACrkLCBNo;
		dAniCrack	= sData.dAniCrack;
		return *this;
	}
};

