// 1way slab design.
struct T_RSL1_PART
{
	int iSlabNo;
	int iLCBNo;
	double dMu[2];
    double dDist[2];
    double dPoint1[3];
    double dPoint2[3];
	void Initialize()
	{
		iSlabNo	= 0;
		iLCBNo	= 0;
		for ( int i = 0 ; i < 2 ; ++i )
		{
			dMu[i]	 = 0.0;
			dDist[i] = 0.0;
		}
		for ( int i = 0 ; i < 3 ; ++i )
		{
			dPoint1[i] = 0.0;
			dPoint2[i] = 0.0;
		}
	}
    T_RSL1_PART() {}
    T_RSL1_PART(const T_RSL1_PART& rData) { *this = rData; }
    T_RSL1_PART& operator= (const T_RSL1_PART& rData)
    {
        iSlabNo	= rData.iSlabNo;
        iLCBNo	= rData.iLCBNo;
        for ( int i = 0 ; i < 2 ; ++i )
        {
            dMu[i]	 = rData.dMu[i]	;
            dDist[i] = rData.dDist[i];
        }
        for ( int i = 0 ; i < 3 ; ++i )
        {
            dPoint1[i] = rData.dPoint1[i];
            dPoint2[i] = rData.dPoint2[i];
        }
        return *this;
    }
};

struct T_RSL1_D
{
	CString strCutLineNa;
    int    iLCBNo;
	double dMu;	// Total Moment.
	double dpMn;
	double dAsReq;
    double dAsUse;
	double dRhoReq;
    double dRhoUse;
	double dRatM;
    int nCriticalElemKey;
    int nCriticalReferKey;
	// MNET:XXXX-HSSHIM-20121119. Eurocode2:04의 NTC2012 기준추가시 중립축비(x/d) 검토 항목추가
    double dRatXd; // (x/d)
    double dLimXd; // (x/d)limit
    T_SLAB_BAR Rebar;
    T_SLAB_BAR AddRebar;	
	CArray<T_RSL1_PART, T_RSL1_PART&> PartList;

	void Initialize()
	{
		strCutLineNa = _T("");
        iLCBNo  = 0;
        dMu		= 0.0;
        dpMn	= 0.0;
		dAsReq	= 0.0;
		dAsUse	= 0.0;
		dRhoReq	= 0.0;
		dRhoUse	= 0.0;
		dRatM	= 0.0;
        nCriticalElemKey = 0;
        nCriticalReferKey = 0;
        dRatXd  = 0.0;
        dLimXd  = 0.0;
        Rebar.Initialize();
        AddRebar.Initialize();
		PartList.RemoveAll();
	}
	T_RSL1_D() {}
	T_RSL1_D(const T_RSL1_D& rData)	{*this = rData;}
	T_RSL1_D& operator = (const T_RSL1_D& rData)
	{
        strCutLineNa  = rData.strCutLineNa;
        iLCBNo        = rData.iLCBNo;
        dMu			  = rData.dMu;
        dpMn		  = rData.dpMn;
        dAsReq		  = rData.dAsReq;
        dAsUse		  = rData.dAsUse;
        dRhoReq       = rData.dRhoReq;
        dRhoUse	      = rData.dRhoUse;
        dRatM		  = rData.dRatM;
        nCriticalElemKey = rData.nCriticalElemKey;
        nCriticalReferKey = rData.nCriticalReferKey;
        dRatXd        = rData.dRatXd;
        dLimXd        = rData.dLimXd;
        Rebar         = rData.Rebar;
        AddRebar      = rData.AddRebar;
		PartList.RemoveAll();
        PartList.Copy(rData.PartList);
        
		return *this;
	}

    double GetXDRatioToLimit() const
    {
        return fabs(dLimXd) < 1.0e-7 ? 99.99 : ( dRatXd / dLimXd );
    }
};

