#define SLAB_FORCE_COMPACT_NUM 48
struct T_SLAB_FORCE_COMPACT
{
	double dForce[SLAB_FORCE_COMPACT_NUM];  // PMS:4352-Seungjun-20110930 EC Inclined slab 24-> 32 -> 48

	void initialize()
	{
		for(int i=0; i<SLAB_FORCE_COMPACT_NUM; i++)
		  dForce[i] = 0.0;
	}
};

struct T_SLAB_FORCE_COMPACT_UNIT
{
	T_SLAB_FORCE_COMPACT_UNIT()
	{
		dForce = D_UNITSYS_BASE_UNITMOMENT;
	}

	int dForce;
};

struct T_SLAB_FORCE_COMPACT_UNIT2
{
	T_SLAB_FORCE_COMPACT_UNIT2()
	{
		for(int i=0; i<12; ++i)
		{
			dForce[i] = D_UNITSYS_BASE_STRESS;
		}
		for(int i=12; i<24; ++i)
		{
			dForce[i] = D_UNITSYS_BASE_UNITFORCE;
		}
	}
	int dForce[24];
};

// PMS:4352-Seungjun-20110930 EC Inclined slab 24-> 32
struct T_SLAB_FORCE_COMPACT_UNIT3
{
	T_SLAB_FORCE_COMPACT_UNIT3()
	{
		for(int i=0; i<12; ++i)
		{
			dForce[i] = D_UNITSYS_BASE_UNITMOMENT;
		}
		for(int i=12; i<32; ++i)
		{
			dForce[i] = D_UNITSYS_BASE_UNITFORCE;
		}
		for(int i=32; i<48; ++i)
		{
			dForce[i] = D_UNITSYS_BASE_STRESS;
		}
	}  
	int dForce[SLAB_FORCE_COMPACT_NUM];
};

// Meshed wall design.
struct T_WALL_POS
{
	int iLCBNo;
	double dStress[3];  // 응력
	double dftd[2];  // 부재력
	double dftn[2];  // 소요응력
	double dAsReq[2], dAsUse[2];
	double dRhoReq[2], dRhoUse[2];
	double dSig_cd;
	double dRat[3];
	double dSpace[2];
	CString strBarSize[2], strRebar[2];
	void Initialize()
	{
		iLCBNo		 = 0;
		for(int i=0; i<2; i++)
		{
			dStress[i] = 0.0;
			dftd[i]    = 0.0;
			dftn[i]    = 0.0;
			dAsReq[i]  = 0.0;
			dAsUse[i]  = 0.0;
			dRhoReq[i]  = 0.0;
			dRhoUse[i]  = 0.0;
			dRat[i]    = 0.0;
			dSpace[i]  = 0.0;
			strBarSize[i] = "";
			strRebar[i]   = "";
		}
		dSig_cd    = 0.0;
		dStress[2] = 0.0;
		dRat[2]    = 0.0;
	}
	T_WALL_POS() {}
	T_WALL_POS(T_WALL_POS& sData)	{*this = sData;}
	T_WALL_POS& operator = (T_WALL_POS& sData)
	{
		iLCBNo		 = sData.iLCBNo;
		for(int i=0; i<2; i++)
		{
			dStress[i] = sData.dStress[i];
			dftd[i]    = sData.dftd[i];
			dftn[i]    = sData.dftn[i];
			dAsReq[i]  = sData.dAsReq[i];
			dAsUse[i]  = sData.dAsUse[i];
			dRhoReq[i] = sData.dRhoReq[i];
			dRhoUse[i] = sData.dRhoUse[i];
			dRat[i]    = sData.dRat[i];
			dSpace[i]  = sData.dSpace[i];
			strBarSize[i] = sData.strBarSize[i];
			strRebar[i]   = sData.strRebar[i];
		}
		dSig_cd    = sData.dSig_cd;
		dStress[2] = sData.dStress[2];
		dRat[2]    = sData.dRat[2];
		return *this;
	}
};

struct T_RMEW_D // Meshed Wall flexural design result.
{
	int iNodeNum;
	double dDw;
	T_WALL_POS Res[iConstMaxNo];

	void Initialize()
	{
		iNodeNum = 0;
		dDw      = 0.0;
		for(int i=0; i<iConstMaxNo; i++)
		{
			Res[i].Initialize();
		}
	}
	T_RMEW_D() {}
	T_RMEW_D(T_RMEW_D& sData)	{*this = sData;}
	T_RMEW_D& operator = (T_RMEW_D& sData)
	{
		iNodeNum	= sData.iNodeNum;
		dDw       = sData.dDw;
		for(int i=0; i<iConstMaxNo; i++)
		{
			Res[i] = sData.Res[i];
		}
		return *this;
	}  
};

