struct T_RISL_D // Inclined slab Top/bottom
{
	int iNodeNum;
	double dB, dT; // Bottom cover, Top Cover
	T_ISLB_POS Bot[iConstMaxNo];
	T_ISLB_POS Top[iConstMaxNo];
	T_ISLB_MID Mid[iConstMaxNo];

	void Initialize()
	{
		iNodeNum = 0;
		dB = 0.0;
		dT = 0.0;
		for(int i=0; i<iConstMaxNo; i++)
		{
			Bot[i].Initialize();
			Top[i].Initialize();
			Mid[i].Initialize();
		}
	}
	T_RISL_D() {}
	T_RISL_D(T_RISL_D& sData)	{*this = sData;}
	T_RISL_D& operator = (T_RISL_D& sData)
	{
		iNodeNum	= sData.iNodeNum;
		dB        = sData.dB;
		dT        = sData.dT;
		for(int i=0; i<iConstMaxNo; i++)
		{
			Bot[i] = sData.Bot[i];
			Top[i] = sData.Top[i];
			Mid[i] = sData.Mid[i];
		}
		return *this;
	}  
};

