{
	int     nNum;
	char    strDia[8];
	double  dDb;
	double  dXi;
	double  dAngle;
	double  dhi;
	BOOL    bGroup;
	int     nGroupNum;
	double  dGroupGap;

	void ConvertToString(T_BURB_SUB_D& rData)
	{
		rData.nNum = nNum;
		ConvertCharStr(strDia, rData.strDia, sizeof(strDia));
		rData.dDb = dDb;
		rData.dXi = dXi;
		rData.dAngle = dAngle;
		rData.dhi = dhi;
		rData.bGroup = bGroup;
		rData.nGroupNum = nGroupNum;
		rData.dGroupGap = dGroupGap;
	}
	
	void ConvertToChar(T_BURB_SUB_D& rData)
	{
		nNum = rData.nNum;
		ConvertStrChar(rData.strDia, strDia, sizeof(strDia));
		dDb = rData.dDb;
		dXi = rData.dXi;
		dAngle = rData.dAngle;
		dhi = rData.dhi;
		bGroup = rData.bGroup;
		nGroupNum = rData.nGroupNum;
		dGroupGap = rData.dGroupGap;
	}
};

