struct T_SDFC_D_842
{
	BOOL bSameIJ;  // I==J:TRUE, I!=J:FALSE
	double dLambda[2];
	CArray<T_SDFC_SUB_D, T_SDFC_SUB_D&> aSdfcSub[2];

	void Initialize()
	{
		bSameIJ = TRUE;

		for(int i=0; i<2; ++i)
		{
			dLambda[i] = 0.0;
			aSdfcSub[i].RemoveAll();
		}
	}

	T_SDFC_D_842() {}
	T_SDFC_D_842(const T_SDFC_D_842& rData) { *this = rData; }
	T_SDFC_D_842& operator=(const T_SDFC_D_842& rData)
	{
		bSameIJ = rData.bSameIJ;

		for(int i=0; i<2; ++i)
		{
			dLambda[i] = rData.dLambda[i];
			aSdfcSub[i].Copy(rData.aSdfcSub[i]);
		}

		return *this;
	}
};

struct T_SDFC_D 
{
	BOOL bSameIJ;  // I==J:TRUE, I!=J:FALSE
	double dLambda[2];
	CArray<T_SDFC_SUB_D, T_SDFC_SUB_D&> aSdfcSub[2]; // Steel Girder Fatigue Check Position
	CArray<T_SDFC_SUB_D, T_SDFC_SUB_D&> aConSdfcSub[2]; // Concrete Fatigue Check Position
	CArray<T_SDFC_SUB_D, T_SDFC_SUB_D&> aRebarSdfcSub[2]; // Rebar Fatigue Check Position

	void Initialize()
	{
		bSameIJ = TRUE;
		
		for(int i=0; i<2; ++i)
		{
			dLambda[i] = 0.0;
			aSdfcSub[i].RemoveAll();
			aConSdfcSub[i].RemoveAll();
			aRebarSdfcSub[i].RemoveAll();
		}
	}
	
	T_SDFC_D() {}
	T_SDFC_D(const T_SDFC_D& rData) { *this = rData; }
	T_SDFC_D& operator=(const T_SDFC_D& rData)
	{
		bSameIJ = rData.bSameIJ;
		
		for(int i=0; i<2; ++i)
		{
			dLambda[i] = rData.dLambda[i];
			aSdfcSub[i].Copy(rData.aSdfcSub[i]);
			aConSdfcSub[i].Copy(rData.aConSdfcSub[i]);
			aRebarSdfcSub[i].Copy(rData.aRebarSdfcSub[i]);
		}
		return *this;
	}

	void Convert842(const T_SDFC_D_842 &rData)
	{
		bSameIJ = rData.bSameIJ;

		for(int i=0; i<2; ++i)
		{
			dLambda[i] = rData.dLambda[i];
			aSdfcSub[i].Copy(rData.aSdfcSub[i]);
			aConSdfcSub[i].RemoveAll();
			aRebarSdfcSub[i].RemoveAll();
		}
	}

};

