struct T_SDAP_SUB_DATA
{
	CArray<int, int> aLPropCount[2];
	CArray<T_SDAP_PROP_D, T_SDAP_PROP_D&> aLPropData[2];
	CArray<int, int> aRPropCount[2];
	CArray<T_SDAP_PROP_D, T_SDAP_PROP_D&> aRPropData[2];

	// For Before Composite Local Force
	CArray<int, int> aLPropCountBefore[2];
	CArray<T_SDAP_PROP_D, T_SDAP_PROP_D&> aLPropDataBefore[2];
	CArray<int, int> aRPropCountBefore[2];
	CArray<T_SDAP_PROP_D, T_SDAP_PROP_D&> aRPropDataBefore[2];
	
	void Get(T_SDAP_D& rData)
	{
		for(int i=0; i<2; ++i)
		{
			int j=0, ix=0, ix2=0, nLCountPropData=0, nRCountPropData=0;
			
			int nCountProp = (int)rData.aSdapSub[i].GetSize();
			
			if(aLPropCount[i].GetSize() > 0)
			{
				for(j=0; j<nCountProp; ++j)
				{
					nLCountPropData = aLPropCount[i][ix++];
					rData.aSdapSub[i][j].aLProp.SetSize(nLCountPropData);
					for (int k=0; k< nLCountPropData; ++k)
						rData.aSdapSub[i][j].aLProp[k] = aLPropData[i][ix2++];
				}
			}

			ix=0, ix2=0;

			if(aRPropCount[i].GetSize() > 0)
			{
				for(j=0; j<nCountProp; ++j)
				{
					nRCountPropData = aRPropCount[i][ix++];
					rData.aSdapSub[i][j].aRProp.SetSize(nRCountPropData);
					for (int k=0; k< nRCountPropData; ++k)
						rData.aSdapSub[i][j].aRProp[k] = aRPropData[i][ix2++];
				}
			}

			int nCountPropBefore = (int)rData.aSdapSubBefore[i].GetSize();
			int nLCountPropDataBefore=0, nRCountPropDataBefore=0;

			ix=0, ix2=0;
			if(aLPropCountBefore[i].GetSize() > 0)
			{
				for(j=0; j<nCountPropBefore; ++j)
				{
					nLCountPropDataBefore = aLPropCountBefore[i][ix++];
					rData.aSdapSubBefore[i][j].aLProp.SetSize(nLCountPropDataBefore);
					for (int k=0; k< nLCountPropDataBefore; ++k)
						rData.aSdapSubBefore[i][j].aLProp[k] = aLPropDataBefore[i][ix2++];
				}
			}

			ix=0, ix2=0;
			if(aRPropCountBefore[i].GetSize() > 0)
			{
				for(j=0; j<nCountPropBefore; ++j)
				{
					nRCountPropDataBefore = aRPropCountBefore[i][ix++];
					rData.aSdapSubBefore[i][j].aRProp.SetSize(nRCountPropDataBefore);
					for (int k=0; k< nRCountPropDataBefore; ++k)
						rData.aSdapSubBefore[i][j].aRProp[k] = aRPropDataBefore[i][ix2++];
				}
			}
		}		
	}

	void Get(T_SDAP_D_842& rData)
	{
		for(int i=0; i<2; ++i)
		{
			int j=0, ix=0, ix2=0, nLCountPropData=0, nRCountPropData=0;

			int nCountProp = (int)rData.aSdapSub[i].GetSize();

			if(aLPropCount[i].GetSize() > 0)
			{
				for(j=0; j<nCountProp; ++j)
				{
					nLCountPropData = aLPropCount[i][ix++];
					rData.aSdapSub[i][j].aLProp.SetSize(nLCountPropData);
					for (int k=0; k< nLCountPropData; ++k)
						rData.aSdapSub[i][j].aLProp[k] = aLPropData[i][ix2++];
				}
			}

			ix=0, ix2=0;

			if(aRPropCount[i].GetSize() > 0)
			{
				for(j=0; j<nCountProp; ++j)
				{
					nRCountPropData = aRPropCount[i][ix++];
					rData.aSdapSub[i][j].aRProp.SetSize(nRCountPropData);
					for (int k=0; k< nRCountPropData; ++k)
						rData.aSdapSub[i][j].aRProp[k] = aRPropData[i][ix2++];
				}
			}
		}		
	}

	void Set(T_SDAP_D& crData)
	{
		for(int i=0; i<2; ++i)
		{
			int nCountProp = (int)crData.aSdapSub[i].GetSize();
			aLPropCount[i].RemoveAll();
			aRPropCount[i].RemoveAll();
			aLPropData[i].RemoveAll();
			aRPropData[i].RemoveAll();
						
			int nLCountPropData, nRCountPropData;
			for (int j=0; j<nCountProp; ++j)
			{
				nLCountPropData = (int)crData.aSdapSub[i][j].aLProp.GetSize();
				aLPropCount[i].Add(nLCountPropData);
				for (int k=0; k< nLCountPropData; ++k)
				{
					aLPropData[i].Add(crData.aSdapSub[i][j].aLProp[k]);
				}

				nRCountPropData = (int)crData.aSdapSub[i][j].aRProp.GetSize();
				aRPropCount[i].Add(nRCountPropData);
				for (int k = 0; k< nRCountPropData; ++k)
				{
					aRPropData[i].Add(crData.aSdapSub[i][j].aRProp[k]);
				}
			}

			// For Before Composite Local Force
			int nCountPropBefore = (int)crData.aSdapSubBefore[i].GetSize();
			aLPropCountBefore[i].RemoveAll();
			aRPropCountBefore[i].RemoveAll();
			aLPropDataBefore[i].RemoveAll();
			aRPropDataBefore[i].RemoveAll();

			int nLCountPropDataBefore, nRCountPropDataBefore;
			for (int j=0; j<nCountPropBefore; ++j)
			{
				nLCountPropDataBefore = (int)crData.aSdapSubBefore[i][j].aLProp.GetSize();
				aLPropCountBefore[i].Add(nLCountPropDataBefore);
				for (int k=0; k< nLCountPropDataBefore; ++k)
				{
					aLPropDataBefore[i].Add(crData.aSdapSubBefore[i][j].aLProp[k]);
				}

				nRCountPropDataBefore = (int)crData.aSdapSubBefore[i][j].aRProp.GetSize();
				aRPropCountBefore[i].Add(nRCountPropDataBefore);
				for (int k = 0; k< nRCountPropDataBefore; ++k)
				{
					aRPropDataBefore[i].Add(crData.aSdapSubBefore[i][j].aRProp[k]);
				}
			}
		}		
	} 
};

