struct T_RPSS_D
{
	int nFormula;           // 0: NR/L2/CIV/035 1: BS5400 Part3
	int nReqRouteAvailNum;
	double dConditionFactor;
	int nGamma_m;			// 0:Characteristic Strength, Worst Credible Strength
	int nSpanType;
	double dk2;
	double dk3;
	double dUframeS;        // U-frame Spacing
	BOOL bEqA4;
	BOOL bUserInput;
	T_RPSS_FT_D Factors;

	BOOL bUlsFlexure;		// Ultimate Limit State > Flexure
	BOOL bUlsShear;			// Ultimate Limit State > Shear
	BOOL bUlsFST;			// Ultimate Limit State > Flexure & Shear & Torsion
	BOOL bUlsLgShear;		// Ultimate Limit State > Longitudinal Shear
	BOOL bUlsIntBearStiff;  // Ultimate Limit State > Intermediate and Bearing Stiffener

	BOOL bSlsStress;		// Serviceability Limit State > Stress
	BOOL bSlsLgShear;		// Serviceability Limit State > Longitudinal Shear

	BOOL bRptUltLim;		// Detail Report > Ultimate Limit State
	BOOL bRptServLim;		// Detail Report > Serviceability Limit State

	void Initialize()
	{
		nFormula = 0;
		nReqRouteAvailNum = 0;
		dConditionFactor = 1.0;
		nGamma_m = 0;		
		nSpanType = 0;
		dk2 = 1.0;
		dk3 = 1.0;
		dUframeS = 0.0;
		bEqA4 = TRUE;
		bUserInput = TRUE;
		Factors.Initialize();

		bUlsFlexure = TRUE;
		bUlsShear = TRUE;
		bUlsFST = TRUE;
		bUlsLgShear = TRUE;
		bUlsIntBearStiff = TRUE;
		bSlsStress = TRUE;
		bSlsLgShear = TRUE;
		bRptUltLim = TRUE;
		bRptServLim = TRUE;
	}
	void Convert960temp(T_RPSS_D_960_temp& rData)
	{
		nFormula = rData.nFormula;
		nReqRouteAvailNum = 0;
		dConditionFactor = rData.dConditionFactor;
		nGamma_m = rData.nGamma_m;
		nSpanType = rData.nSpanType;
		dk2 = rData.dk2;
		dk3 = rData.dk3;
		dUframeS = rData.dUframeS;
		bEqA4 = rData.bEqA4;
		bUserInput = rData.bUserInput;
		Factors.Convert955(rData.Factors);		

		bUlsFlexure = rData.bUlsFlexure;
		bUlsShear = rData.bUlsShear;
		bUlsFST = rData.bUlsFST;
		bUlsLgShear = rData.bUlsLgShear;
		bUlsIntBearStiff = FALSE;
		bSlsStress = rData.bSlsStress;
		bSlsLgShear = rData.bSlsLgShear;
		bRptUltLim = rData.bRptUltLim;
	}
	void Convert955(T_RPSS_D_955& rData)
	{
		nFormula = 0;
		nReqRouteAvailNum = 0;
		dConditionFactor = rData.dConditionFactor;
		nGamma_m = rData.nGamma_m;
		nSpanType = 0;
		dk2 = 1.0;
		dk3 = 1.0;
		dUframeS = 0.0;
		bEqA4 = TRUE;
		bUserInput = rData.bUserInput;
		Factors.Convert955(rData.Factors);

		bUlsFlexure = rData.bUlsFlexure;
		bUlsShear = rData.bUlsShear;
		bUlsFST = rData.bUlsFST;
		bUlsLgShear = rData.bUlsLgShear;
		bUlsIntBearStiff = FALSE;
		bSlsStress = rData.bSlsStress;
		bSlsLgShear = rData.bSlsLgShear;
		bRptUltLim = rData.bRptUltLim;
		bRptServLim = rData.bRptServLim;
	}
};

